    + GG(gira ? 'h_in_spin' : '', `<path d="M${x + 22},${y - 34} q9,-8 18,0 q-4,10 -18,0z" fill="#E57373"/><path d="M${x + 25},${y - 24} q8,4 13,-2" stroke="#FFF59D" stroke-width="4" fill="none"/><circle cx="${x + 31}" cy="${y - 30}" r="15" fill="none"/>`);
