    + GG('h_in_fl', `<path d="M${x + 20},${y - 16} q-2,-12 8,-20 q0,8 5,9 q2,-8 8,-12 q6,12 2,23z" fill="#FF7043"/><path d="M${x + 26},${y - 16} q0,-7 5,-11 q3,5 6,11z" fill="#FFCA28"/>`);
  const lena = (x, y, n = 3) => { let g = ''; for (let r = 0; r < n; r++) for (let c = 0; c < 4 - r; c++) { const cx = x + c * 16 + r * 8 + 8, cy = y - 7 - r * 13; g += `<circle cx="${cx}" cy="${cy}" r="7" fill="#A1887F" stroke="#5D4037" stroke-width="1.5"/><circle cx="${cx}" cy="${cy}" r="3" fill="none" stroke="#6D4C41"/>`; } return g; };
  const papel = (x, y, w, h, tit, c = '#0E3962') => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="#fff" stroke="#90A4AE" stroke-width="1.5"/><rect x="${x}" y="${y}" width="${w}" height="16" rx="3" fill="${c}"/>${tit ? TT(x + w / 2, y + 12, tit, 10, '#fff') : ''}${[0, 1, 2, 3, 4, 5, 6].filter(i => 24 + i * 8 < h - 4).map(i => `<rect x="${x + 6}" y="${y + 22 + i * 8}" width="${w - 12 - (i % 2) * 10}" height="3" fill="#B0BEC5"/>`).join('')}`;
  const tel = (x, y) => `<rect x="${x}" y="${y}" width="14" height="24" rx="3" fill="#263238"/><rect x="${x + 2}" y="${y + 3}" width="10" height="15" fill="#80DEEA"/>`;
  const cono = (x, y = 184) => `<path d="M${x - 9},${y} L${x - 3},${y - 32} H${x + 3} L${x + 9},${y}Z" fill="#FF6D00"/><rect x="${x - 6}" y="${y - 20}" width="12" height="5" fill="#fff"/><rect x="${x - 12}" y="${y - 2}" width="24" height="5" rx="1" fill="#E65100"/>`;
  const cinta = (x1, x2, y) => `<line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#fff" stroke-width="6"/><line x1="${x1}" y1="${y}" x2="${x2}" y2="${y}" stroke="#D7262B" stroke-width="6" stroke-dasharray="10 10"/>`;
  const salida = (x, y) => `<rect x="${x}" y="${y}" width="66" height="22" rx="3" fill="#2E7D32"/>${TT(x + 27, y + 15, 'SALIDA', 11, '#fff')}${arr(x + 51, y + 11, x + 62, y + 11, '#fff', 2.5)}`;
  const zseg = (x, y) => `<rect x="${x}" y="${y}" width="96" height="40" rx="4" fill="#2E7D32" stroke="#fff" stroke-width="2"/>` + TT(x + 48, y + 16, 'ZONA DE', 11, '#fff') + TT(x + 48, y + 31, 'SEGURIDAD', 11, '#fff');
  const nofumar = (x, y, r = 15) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#D7262B" stroke-width="4"/><rect x="${f1(x - r * .6)}" y="${y - 2}" width="${f1(r)}" height="5" fill="#455A64"/><rect x="${f1(x + r * .4)}" y="${y - 2}" width="${f1(r * .25)}" height="5" fill="#FF7043"/><line x1="${f1(x - r * .7)}" y1="${f1(y - r * .7)}" x2="${f1(x + r * .7)}" y2="${f1(y + r * .7)}" stroke="#D7262B" stroke-width="4"/>`;
  const prohibe = (x, y, r = 16) => `<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="#D7262B" stroke-width="${f1(r * .2)}"/><line x1="${f1(x - r * .7)}" y1="${f1(y - r * .7)}" x2="${f1(x + r * .7)}" y2="${f1(y + r * .7)}" stroke="#D7262B" stroke-width="${f1(r * .2)}"/>`;
  const raton = (x, y) => `<path d="M${x - 12},${y + 1} C${x - 30},${y + 6} ${x - 40},${y - 6} ${x - 56},${y - 2}" stroke="#6D4C41" stroke-width="2" fill="none" stroke-linecap="round"/><ellipse cx="${x}" cy="${y - 3}" rx="13" ry="7" fill="#8D6E63"/><circle cx="${x + 12}" cy="${y - 6}" r="5.5" fill="#8D6E63"/><circle cx="${x + 10}" cy="${y - 12}" r="3.4" fill="#F8BBD0" stroke="#8D6E63"/><circle cx="${x + 15}" cy="${y - 7}" r="1.2" fill="#111"/><circle cx="${x + 18}" cy="${y - 5}" r="1.3" fill="#F06292"/>`;
  const guante = (x, y, c = '#FDD835', roto) => `<rect x="${x}" y="${y - 20}" width="22" height="20" rx="5" fill="${c}" stroke="#22303A" stroke-width="1.2"/>${[0, 1, 2, 3].map(i => `<rect x="${f1(x + 1 + i * 5.3)}" y="${y - 33 + (i === 0 || i === 3 ? 3 : 0)}" width="5" height="16" rx="2.5" fill="${c}" stroke="#22303A" stroke-width="1"/>`).join('')}<ellipse cx="${x - 3}" cy="${y - 12}" rx="4" ry="7" transform="rotate(-25 ${x - 3} ${y - 12})" fill="${c}" stroke="#22303A" stroke-width="1"/>`
