  const rayo = (x, y, s = 1) => `<path d="M${x},${y} l${-8 * s},${16 * s} h${7 * s} l${-5 * s},${14 * s} l${14 * s},${-19 * s} h${-7 * s} l${5 * s},${-11 * s}z" fill="#FFC20E" stroke="#263238" stroke-width="1.2"/>`;
  const auto = (x, y, c = '#0E3962', s = 1) => { const S = v => f1(v * s); return `<g transform="translate(${x},${y}) scale(${s})"><path d="M0,-14 v-20 q0,-6 6,-7 l22,-3 l20,-18 h58 l18,18 h22 q10,0 10,10 v20z" fill="${c}" stroke="#0A2A4A" stroke-width="2"/><rect x="0" y="-30" width="156" height="4" fill="#D4A537"/><path d="M52,-58 l-16,16 h34 v-16z M76,-58 v16 h40 l-14,-16z" fill="#B3E5FC" stroke="#0A2A4A"/><circle cx="34" cy="-12" r="13" fill="#263238"/><circle cx="34" cy="-12" r="5" fill="#B0BEC5"/><circle cx="124" cy="-12" r="13" fill="#263238"/><circle cx="124" cy="-12" r="5" fill="#B0BEC5"/><rect x="150" y="-34" width="8" height="6" rx="2" fill="#FFF59D"/></g>`; };
  const bici = (x, y) => `<circle cx="${x}" cy="${y - 14}" r="14" fill="none" stroke="#263238" stroke-width="3"/><circle cx="${x + 50}" cy="${y - 14}" r="14" fill="none" stroke="#263238" stroke-width="3"/><path d="M${x},${y - 14} l16,-24 h24 l10,24 M${x + 16},${y - 38} l10,24 l14,-24 M${x + 40},${y - 38} l-2,-8 h8" stroke="#D32F2F" stroke-width="3" fill="none" stroke-linejoin="round"/><circle cx="${x + 26}" cy="${y - 14}" r="3" fill="#263238"/>`;
  const casa = (x, y) => `<path d="M${x},${y - 44} l34,-28 l34,28 v44 h-68z" fill="#FFE0B2" stroke="#8D6E63" stroke-width="2"/><path d="M${x - 6},${y - 42} l40,-34 l40,34" fill="none" stroke="#C62828" stroke-width="5"/><rect x="${x + 26}" y="${y - 26}" width="16" height="26" fill="#8D6E63"/><rect x="${x + 6}" y="${y - 36}" width="14" height="12" fill="#BBDEFB" stroke="#8D6E63"/>`;
  const escritorio = (x, y, w = 110) => `<rect x="${x}" y="${y - 40}" width="${w}" height="6" fill="#8D6E63"/><rect x="${x + 4}" y="${y - 34}" width="5" height="34" fill="#6D4C41"/><rect x="${x + w - 9}" y="${y - 34}" width="5" height="34" fill="#6D4C41"/>`
    + `<rect x="${x + 24}" y="${y - 82}" width="54" height="36" rx="3" fill="#263238"/><rect x="${x + 28}" y="${y - 78}" width="46" height="28" fill="#4FC3F7"/><rect x="${x + 46}" y="${y - 46}" width="10" height="6" fill="#455A64"/><rect x="${x + 22}" y="${y - 43}" width="44" height="3" fill="#37474F"/>`;
