  const motosierra = (x, y, flip) => { const g = `<rect x="${x}" y="${y - 10}" width="24" height="16" rx="4" fill="#FF6F00" stroke="#263238" stroke-width="1.2"/><path d="M${x + 4},${y - 10} q8,-10 16,0" stroke="#263238" stroke-width="2.5" fill="none"/><rect x="${x + 24}" y="${y - 6}" width="40" height="8" rx="4" fill="#B0BEC5" stroke="#455A64"/><path d="M${x + 26},${y - 7} h36 M${x + 26},${y + 3} h36" stroke="#263238" stroke-width="1.5" stroke-dasharray="3 2" class="h_in_wf"/>`; return flip ? `<g transform="translate(${2 * x + 64},0) scale(-1,1)">${g}</g>` : g; };
  const orilladora = (x1, y1, x2, y2) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#FF6F00" stroke-width="4" stroke-linecap="round"/><rect x="${x1 - 6}" y="${y1 - 6}" width="14" height="12" rx="3" fill="#FF6F00" stroke="#263238"/><path d="M${x2 - 10},${y2 + 2} a10,5 0 0 1 20,0" fill="#455A64"/>` + GG('h_in_spin', `<path d="M${x2 - 12},${y2 + 3} h24 M${x2},${y2 - 2} v10" stroke="#263238" stroke-width="1.5"/>`);
