  SI_CONT.temas.push({
    id: 'pisos', sec: 'todos', emp: ['hotel'], title: 'Pisos mojados, resbalones y caídas al mismo nivel', thumb: 'h_t1_s_letrero', mins: 12,
    learn: [
      { s: 'h_t1_s_intro', t: 'La caída más común', x: 'Las <b>caídas al mismo nivel</b>, es decir, resbalar o tropezar en el piso donde caminas, son de los accidentes más frecuentes en un hotel. Parecen menores, pero causan <b>esguinces, fracturas de muñeca y cadera y golpes en la cabeza</b>. Sus causas típicas: piso mojado o con grasa, objetos en el paso, apuro, mal calzado y poca luz.' },
      { s: 'h_t1_s_banos', t: 'Baños de las habitaciones', x: 'El agua y el jabón de la ducha dejan el piso muy resbaladizo.<ul><li>Pon el letrero de piso mojado en la puerta mientras limpias.</li><li>Trapea por partes, de adentro hacia la salida, dejando un camino seco.</li><li>No te pares sobre el borde de la tina ni de la ducha para limpiar arriba.</li><li>Seca de inmediato el agua que quede en el piso.</li></ul>' },
      { s: 'h_t1_s_cocina', t: 'Cocina: agua, grasa y aceite', x: 'En la cocina se suman agua, grasa y aceite.<ul><li>Si algo se derrama, <b>límpialo de inmediato</b> y señaliza mientras se seca.</li><li>El aceite se recoge primero con papel o un paño, y después se lava: con agua sola se esparce.</li><li>Mantén limpios los pisos antideslizantes y las rejillas.</li><li>No corras, y menos con ollas o cuchillos en las manos.</li></ul>' },
      { s: 'h_t1_s_piscina', t: 'Piscina y áreas verdes', x: '<ul><li>El <b>borde de la piscina</b> mojado resbala: camina despacio y con calzado antideslizante.</li><li>El <b>pasto mojado</b> por el rocío, la lluvia o el riego, la escarcha del invierno y las hojas en el sendero también resbalan.</li><li>En pendientes del parque, pisa firme y usa los senderos.</li><li>Mira dónde pisas: hoyos, raíces y mangueras.</li></ul>' },
      { s: 'h_t1_s_esc', t: 'Escaleras: siempre del pasamanos', x: '<ul><li><b>Tómate del pasamanos</b>, al subir y al bajar.</li><li>No corras ni saltes peldaños.</li><li>No lleves una carga que te tape la vista o te ocupe las dos manos: usa el carro o pide ayuda.</li><li>No uses el celular en la escalera.</li><li>Avisa si un peldaño está suelto, mojado o la luz está quemada.</li></ul>' },
      { s: 'h_t1_s_letrero', t: 'El letrero de piso mojado', x: '<ul><li><b>Ponlo antes</b> de mojar el piso, donde se vea desde ambos lados.</li><li>Déjalo hasta que el piso esté seco.</li><li><b>Retíralo</b> cuando ya está seco: si queda siempre puesto, nadie lo respeta.</li></ul>El letrero avisa, pero no seca el piso: lo más seguro es limpiar por partes y dejar un camino seco para que pasen los huéspedes.', k: 'El letrero se pone antes de mojar y se retira cuando el piso está seco.' },
      { s: 'h_t1_s_calzado', t: 'Calzado cerrado y antideslizante', x: 'Usa siempre <b>calzado cerrado y antideslizante</b>, que afirme bien el pie. Revisa la suela: si está lisa o gastada, ya no agarra y hay que cambiarlo. Nada de sandalias, chalas ni zuecos abiertos atrás. En mantención, el calzado de seguridad que pide la tarea.' },
      { s: 'h_t1_s_correr', t: 'No corras y mira por dónde vas', x: 'La mayoría de las caídas pasan por <b>apuro o distracción</b>.<ul><li>Camina, no corras, aunque estés atrasado.</li><li>No camines mirando el celular.</li><li>Mira el piso: alfombras levantadas, cables, juguetes de niños.</li><li>Avisa de inmediato las baldosas sueltas, alfombras levantadas o luces quemadas.</li></ul>', k: 'Camina, no corras, aunque estés apurado.' }
    ],
    quiz: [
      { s: 'h_t1_s_intro', v: [
        { q: '¿Qué es una caída al mismo nivel?', o: ['Resbalar o tropezar en el mismo piso donde caminas', 'Caer desde una escala o un techo', 'Caer a la piscina desde el trampolín', 'Que se caiga un objeto desde una repisa'], w: 'Es caer en el plano por donde se camina, por resbalón o tropiezo.' },
        { q: '¿Cuál de estas es una causa típica de caídas al mismo nivel?', o: ['Piso mojado, apuro y mal calzado', 'El uso del pasamanos', 'La buena iluminación', 'El letrero de piso mojado'], w: 'Agua, grasa, objetos en el paso, apuro, mal calzado y poca luz causan resbalones y tropiezos.' },
        { q: 'Las caídas al mismo nivel siempre son leves.', vf: false, w: 'Falso. Pueden causar fracturas de muñeca o cadera y golpes graves en la cabeza.' } ] },
      { s: 'h_t1_s_banos', v: [
        { q: 'Vas a trapear el baño de una habitación. ¿Cómo lo haces?', o: ['Por partes, de adentro hacia la salida, dejando un camino seco', 'Mojando todo el piso de una vez', 'Desde la puerta hacia adentro, pisando lo mojado', 'Con mucha agua y sin secar'], w: 'Así no pisas lo recién mojado y dejas un paso seco.' },
        { q: 'Para limpiar la parte alta del baño, ¿te paras sobre el borde de la tina?', o: ['No, uso una escala adecuada o un mango largo', 'Sí, si me afirmo bien de la cortina', 'Sí, si el borde de la tina está seco', 'Sí, si es solo por un rato corto'], w: 'El borde de la tina es angosto y resbaladizo: no es una escala.' },
        { q: 'Mientras limpias el baño, el letrero de piso mojado se pone en la puerta.', vf: true, w: 'Verdadero. Avisa a quien entre que el piso está mojado.' } ] },
      { s: 'h_t1_s_cocina', v: [
        { q: 'Se derramó aceite en el piso de la cocina. ¿Qué haces?', o: ['Lo recojo con papel o paño, lavo y señalizo hasta que seque', 'Le echo bastante agua para que se vaya', 'Lo dejo así y aviso al final del turno', 'Le pongo una caja encima para taparlo'], w: 'Con agua sola el aceite se esparce. Primero se absorbe, después se lava y se señaliza.' },
        { q: '¿Cuándo se limpia un derrame en la cocina?', o: ['De inmediato', 'Al terminar el servicio', 'Cuando alguien se resbala', 'Al día siguiente'], w: 'Un derrame se limpia de inmediato y se señaliza mientras se seca.' },
        { q: 'En la cocina se puede correr si hay mucho trabajo, siempre que se tenga cuidado.', vf: false, w: 'Falso. En la cocina no se corre, y menos con ollas o cuchillos.' } ] },
      { s: 'h_t1_s_piscina', v: [
        { q: '¿Por qué hay que tener cuidado con el pasto en las mañanas?', o: ['Porque el rocío o la escarcha lo dejan resbaladizo', 'Porque en la mañana crece más rápido', 'Porque con el sol de la mañana se ve más verde', 'Porque el pasto se riega solo de noche'], w: 'El pasto mojado por rocío, lluvia, riego o escarcha resbala.' },
        { q: '¿Cómo se camina por el borde de la piscina?', o: ['Despacio y con calzado antideslizante', 'Rápido, para mojarse menos', 'Descalzo, para sentir el piso', 'Corriendo por la orilla seca'], w: 'El borde mojado resbala: se camina despacio y con buen calzado.' },
        { q: '¿Qué más debes mirar al caminar por el parque?', o: ['Hoyos, raíces, mangueras y hojas en el sendero', 'Solo la hora y los mensajes en el celular', 'Solo el cielo, por si empieza a llover', 'Nada, porque el parque es todo plano'], w: 'Hoyos, raíces y mangueras causan tropiezos; las hojas mojadas resbalan.' } ] },
      { s: 'h_t1_s_esc', v: [
        { q: '¿Cuál es la regla básica para usar las escaleras del hotel?', o: ['Tomarse del pasamanos al subir y al bajar', 'Bajar rápido para no atrasarse', 'Saltar el último peldaño', 'Llevar la carga con las dos manos'], w: 'El pasamanos te sostiene si pisas mal.' },
        { q: 'Tienes que subir varias toallas y sábanas por la escalera. ¿Qué haces?', o: ['Llevo poca carga para tener una mano libre, o pido ayuda', 'Subo todo junto aunque no vea los peldaños', 'Subo corriendo para terminar antes de tiempo', 'Lanzo la ropa desde abajo al piso de arriba'], w: 'Una carga que tapa la vista u ocupa las dos manos te impide ver y afirmarte.' },
        { q: 'Usar el celular mientras bajas la escalera está bien si vas despacio.', vf: false, w: 'Falso. El celular te distrae de los peldaños. Se usa en un lugar seguro, detenido.' } ] },
      { s: 'h_t1_s_letrero', v: [
        { q: '¿Cuándo se pone el letrero de piso mojado?', o: ['Antes de mojar el piso', 'Cuando alguien se resbala', 'Al terminar de secar', 'Solo si hay huéspedes cerca'], w: 'El letrero se pone antes, para avisar desde el primer momento.' },
        { q: '¿Cuándo se retira el letrero de piso mojado?', o: ['Cuando el piso ya está seco', 'Nunca: se deja puesto todo el día', 'Apenas terminas de trapear', 'Cuando termina el turno'], w: 'Si queda siempre puesto, la gente deja de respetarlo.' },
        { q: 'El letrero de piso mojado seca el piso y elimina el riesgo.', vf: false, w: 'Falso. Solo avisa. Lo más seguro es limpiar por partes y dejar un camino seco.' } ] },
      { s: 'h_t1_s_calzado', v: [
        { q: '¿Qué calzado corresponde para trabajar en el hotel?', o: ['Cerrado y antideslizante, que afirme el pie', 'Sandalias livianas, por el calor', 'Zuecos de goma abiertos atrás', 'Cualquiera, mientras sea cómodo'], w: 'El calzado cerrado y antideslizante evita resbalones y torceduras.' },
        { q: 'La suela de tus zapatos ya está lisa. ¿Qué significa?', o: ['Que ya no agarra bien y hay que cambiarlos', 'Que los zapatos están recién lustrados', 'Que ahora resbalan menos que antes', 'Nada, porque la suela no importa'], w: 'Una suela gastada pierde agarre y aumenta el riesgo de resbalar.' },
        { q: 'En mantención se usa el calzado de seguridad que pide la tarea.', vf: true, w: 'Verdadero. Cada tarea de mantención tiene su calzado y su EPP.' } ] },
      { s: 'h_t1_s_correr', v: [
        { q: 'Estás atrasado para preparar una habitación. ¿Cómo te desplazas?', o: ['Camino, sin correr, mirando por dónde voy', 'Corro por el pasillo', 'Bajo la escalera de dos en dos', 'Voy mirando el celular para avisar que voy'], w: 'El apuro es causa de muchas caídas: se camina siempre.' },
        { q: 'Ves una alfombra del pasillo levantada en una esquina. ¿Qué haces?', o: ['Aviso de inmediato para que la reparen', 'Paso por encima con cuidado', 'La dejo así, nadie se ha caído', 'La tapo con un mueble del pasillo'], w: 'Una alfombra levantada es una condición insegura: se avisa de inmediato.' },
        { q: 'La mayoría de las caídas al mismo nivel se relacionan con apuro o distracción.', vf: true, w: 'Verdadero. Caminar atento y sin apuro evita la mayoría de los resbalones y tropiezos.' } ] }
    ]
  });

