  const pastoAlto = (x0, x1, y) => { let g = ''; for (let x = x0; x <= x1; x += 6) g += `<path d="M${x},${y} q${-2 + (x % 4)},-14 ${-4 + (x % 7)},-${18 + (x % 9)}" stroke="${x % 2 ? '#558B2F' : '#689F38'}" stroke-width="2" fill="none"/>`; return G('h_t2_w', g); };
