  S.h_t2_h_ventilar_q = () => sc(H.fondo.jardin() + K(30, 176, .5, caseta('cerrada')) + W(200, 176, Object.assign({ flip: true, face: 'worried' }, MAN)) + G('h_t2_p', T(250, 70, '?', 30, '#F9A825')));
