  const orilladora = (x, y, gira = true) => `<line x1="${x}" y1="${y}" x2="${x + 46}" y2="${y + 52}" stroke="#455A64" stroke-width="3"/><rect x="${x - 10}" y="${y - 6}" width="16" height="10" rx="3" fill="#F57C00" stroke="${OL}"/>`
