  S.h_t2_l_escalera = () => sc(H.fondo.pasillo() + escalera(60, 165, 6, 26, 13) + conCel(151, 165 - 13 * 3, Object.assign({ face: 'ok' }, REC)) + G('h_t2_sh', `<path d="M145,128 q-6,4 -2,10" stroke="#C62828" stroke-width="2" fill="none"/>`) + no(296, 24) + pill(80, 16, 'Nunca en escaleras', '#C62828', 10));
  S.h_t2_l_conducir = () => sc(calle() + K(60, 192, .5, auto('#0E3962')) + `<rect x="60" y="168" width="215" height="4" fill="#D4A537"/>` + conductor(true) + G('h_t2_p', `<circle cx="223" cy="138" r="9" fill="none" stroke="#C62828" stroke-width="2.5"/>`) + no(296, 24) + pill(110, 20, 'Nunca al conducir', '#C62828', 10));
