      { s: 'h_t2_l_huesped', v: [
        { q: 'Estás atendiendo a un huésped y te llega un mensaje. ¿Qué haces?', o: ['Sigo atendiendo y no miro el celular', 'Leo el mensaje y después sigo', 'Le pido que espere mientras respondo', 'Respondo mientras le hablo'], w: 'Durante la atención, el huésped tiene toda tu atención.' },
        { q: '¿Se pueden tomar fotos de los huéspedes o de sus habitaciones?', o: ['No, nunca', 'Sí, si no se dan cuenta', 'Sí, para mostrarlas a mis amigos', 'Solo de sus pertenencias'], w: 'Es su privacidad. Nunca se toman fotos de huéspedes, de sus cosas ni de sus habitaciones.' },
        { q: '¿Dónde no debes cargar tu celular?', o: ['En enchufes de la cocina, la lavandería o las habitaciones', 'Donde la jefatura lo autorice', 'En el lugar habilitado para el personal', 'En tu casa'], w: 'Los cables y cargadores en esos lugares son un riesgo eléctrico y de tropiezo.' }] },
      { s: 'h_t2_l_emerg_q', v: [
        { q: '¿A qué número llamas ante un accidente del trabajo?', o: ['ACHS 1404', 'Bomberos 132', 'Carabineros 133', 'El número de un compañero'], w: 'La ACHS atiende los accidentes del trabajo en el 1404. El SAMU es el 131.' },
        { q: 'Hay una emergencia en el hotel. ¿Qué haces primero?', o: ['Me pongo en un lugar seguro y después llamo', 'Grabo un video para mostrar lo que pasa', 'Llamo mientras corro por la escalera', 'Busco la mejor señal sin moverme del peligro'], w: 'Tu seguridad es primero. Desde un lugar seguro avisas y pides ayuda.' },
        { q: '¿Cuál es el número de Bomberos?', o: ['132', '131', '133', '1404'], w: 'Bomberos 132, SAMU 131, Carabineros 133 y ACHS 1404.' }] }
