    + '.h_co_dr{animation:hCoDr .8s linear infinite}@keyframes hCoDr{from{stroke-dashoffset:0}to{stroke-dashoffset:-16}}'
    + '.h_co_bub{animation:hCoBub 1.1s ease-in infinite;transform-box:fill-box}@keyframes hCoBub{0%{opacity:0;transform:translateY(3px)}50%{opacity:1}100%{opacity:0;transform:translateY(-4px)}}'
    + '.h_co_sn{animation:hCoSn 3.2s linear infinite}@keyframes hCoSn{0%{transform:translateY(-12px);opacity:0}20%{opacity:1}100%{transform:translateY(40px);opacity:0}}'
    + '.h_co_pu{animation:hCoPu 1.2s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 50%}@keyframes hCoPu{50%{transform:scale(1.18)}}'
    + '.h_co_sh{animation:hCoSh .18s linear infinite alternate}@keyframes hCoSh{from{transform:translateX(-1.5px)}to{transform:translateX(1.5px)}}'
    + '.h_re_lz{animation:hReLz 2.6s ease-in-out infinite alternate;transform-box:view-box}@keyframes hReLz{from{transform:rotate(-9deg)}to{transform:rotate(7deg)}}'
    + '.h_re_ga{animation:hReGa 1.6s ease-in-out infinite;transform-box:fill-box;transform-origin:50% 50%}@keyframes hReGa{0%,100%{opacity:.35}50%{opacity:1}}'
    + '</style>';
  const Z = (fondo, inner) => sv(ST + fondo + inner);
  const C = o => Object.assign({ area: 'cocina' }, o || {});
  const pill = (x, y, s, c = '#1565C0', fs = 11) => H.pill(x, y, s, c, fs);
  const arr = (x1, y1, x2, y2, c = '#2E7D32', w = 3) => { const a = Math.atan2(y2 - y1, x2 - x1), h = 8; return `<line x1="${x1}" y1="${y1}" x2="${(x2 - Math.cos(a) * 5).toFixed(1)}" y2="${(y2 - Math.sin(a) * 5).toFixed(1)}" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/><path d="M${x2},${y2} L${(x2 - h * Math.cos(a - .5)).toFixed(1)},${(y2 - h * Math.sin(a - .5)).toFixed(1)} L${(x2 - h * Math.cos(a + .5)).toFixed(1)},${(y2 - h * Math.sin(a + .5)).toFixed(1)}Z" fill="${c}"/>`; };
  const linea = (x1, y1, x2, y2, c = '#1565C0') => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" stroke-width="2"/>`;
  const aro = (x, y, r = 14, c = '#D7262B') => `<circle class="h_co_bl" cx="${x}" cy="${y}" r="${r}" fill="none" stroke="${c}" stroke-width="3"/>`;
  const prohibido = (x, y, r = 13) => `<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="#D7262B" stroke-width="3"/><line x1="${x - r * .7}" y1="${y - r * .7}" x2="${x + r * .7}" y2="${y + r * .7}" stroke="#D7262B" stroke-width="3"/>`;
  const vap = (cx, y, k = 1, c = '#CFD8DC') => `<g class="h_co_st"><path d="M${cx - 5 * k},${y} q${-4 * k},${-6 * k} 0,${-11 * k} q${4 * k},${-5 * k} 0,${-10 * k}" stroke="${c}" stroke-width="${2.5 * k}" fill="none" stroke-linecap="round"/></g><g class="h_co_st h_co_st2"><path d="M${cx + 5 * k},${y} q${4 * k},${-6 * k} 0,${-11 * k} q${-4 * k},${-5 * k} 0,${-10 * k}" stroke="${c}" stroke-width="${2.5 * k}" fill="none" stroke-linecap="round"/></g>`;
  const llama = (cx, y, w = 10, c = '#42A5F5', c2) => `<g class="h_co_fl"><path d="M${cx - w / 2},${y} q${w * .1},${-w * .7} ${w / 2},${-w * 1.05} q${w * .4},${w * .35} ${w / 2},${w * 1.05} z" fill="${c}"/>${c2 ? `<path d="M${cx - w / 4},${y} q${w * .05},${-w * .4} ${w / 4},${-w * .6} q${w * .2},${w * .2} ${w / 4},${w * .6} z" fill="${c2}"/>` : ''}</g>`;
  const fuego = (cx, y, w = 40) => `<g class="h_co_fl"><path d="M${cx - w / 2},${y} q${-w * .05},${-w * .5} ${w * .15},${-w * .8} q${w * .02},${w * .3} ${w * .15},${w * .3} q${-w * .05},${-w * .6} ${w * .25},${-w * 1} q${w * .1},${w * .5} ${w * .22},${w * .6} q${w * .1},${-w * .2} ${w * .05},${-w * .5} q${w * .3},${w * .4} ${w * .18},${w * .9} z" fill="#FF7043"/><path d="M${cx - w / 4},${y} q0,${-w * .35} ${w * .15},${-w * .55} q${w * .05},${w * .25} ${w * .12},${w * .25} q${w * .02},${-w * .3} ${w * .12},${-w * .45} q${w * .15},${w * .35} ${w * .08},${w * .75} z" fill="#FFCA28"/></g>`;
  // mano grande (primeros planos), vista lateral. o.glove = color del guante
  const puno = (x, y, s = 1, c = SK) => `<g transform="translate(${x},${y}) scale(${s})"><rect x="-11" y="-9" width="22" height="18" rx="8" fill="${c}" stroke="${OL}" stroke-width="1.2"/><path d="M-6,-9 v18 M0,-9 v18 M6,-9 v18" stroke="${OL}" stroke-width=".7" opacity=".45"/><rect x="-14" y="-6" width="7" height="11" rx="3.5" fill="${c}" stroke="${OL}" stroke-width="1"/></g>`;
  const brazo = (x1, y1, x2, y2, c = '#FFFFFF', w = 16) => `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${OL}" stroke-width="${w + 2.4}" stroke-linecap="round"/><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
  const malla = id => `<defs><pattern id="${id}" width="5" height="5" patternUnits="userSpaceOnUse"><circle cx="2.5" cy="2.5" r="1.6" fill="none" stroke="#546E7A" stroke-width=".7"/></pattern></defs>`;

  // ---------- COCINA: objetos ----------
  // mesón de acero inoxidable (cubierta a 90 centímetros = y 120)
  const meson = (x, w, top = MT) => `<rect x="${x + 5}" y="${top}" width="4" height="${FL - top}" fill="#90A4AE"/><rect x="${x + w - 9}" y="${top}" width="4" height="${FL - top}" fill="#90A4AE"/><rect x="${x + 5}" y="${FL - 18}" width="${w - 10}" height="4" fill="#B0BEC5" stroke="#78909C" stroke-width=".8"/><rect x="${x}" y="${top}" width="${w}" height="6" rx="1" fill="#E3E8EB" stroke="#78909C" stroke-width="1.2"/>`;
  // tabla de picar con paño húmedo debajo; top = cubierta del mesón
  const tabla = (x, top, w = 44, pano = true) => (pano ? `<path d="M${x - 4},${top} h${w + 8} l-1,2.5 h${-(w + 6)} z" fill="#4FC3F7"/>` : '') + `<rect x="${x}" y="${top - (pano ? 5 : 4)}" width="${w}" height="4" rx="1" fill="#D7A86E" stroke="#8D6E3F" stroke-width=".8"/>`;
  // cuchillo: mango a la izquierda del punto (x, y), hoja hacia la derecha (filo abajo)
  const knife = (x, y, r = 0, s = 1, m = '#263238') => `<g transform="translate(${x},${y}) rotate(${r}) scale(${s})"><rect x="-15" y="-3" width="15" height="6" rx="2.5" fill="${m}"/><circle cx="-11" cy="0" r="1" fill="#B0BEC5"/><circle cx="-5" cy="0" r="1" fill="#B0BEC5"/><path d="M0,-3.5 H24 Q33,-3 36,3 H0 Z" fill="#E0E6EA" stroke="#78909C" stroke-width=".8"/></g>`;
  const knifeSierra = (x, y, r = 0, s = 1) => `<g transform="translate(${x},${y}) rotate(${r}) scale(${s})"><rect x="-15" y="-3" width="15" height="6" rx="2.5" fill="#5D4037"/><path d="M0,-3 H38 Q40,0 38,3 ${[...Array(9)].map((_, i) => `L${34 - i * 4},3 L${32 - i * 4},5`).join(' ')} L0,3 Z" fill="#E0E6EA" stroke="#78909C" stroke-width=".8"/></g>`;
  const knifeChico = (x, y, r = 0, s = 1) => `<g transform="translate(${x},${y}) rotate(${r}) scale(${s})"><rect x="-13" y="-2.5" width="13" height="5" rx="2" fill="#1565C0"/><path d="M0,-2.5 H14 Q20,-2 22,2.5 H0 Z" fill="#E0E6EA" stroke="#78909C" stroke-width=".8"/></g>`;
  // olla con dos asas (vista de frente)
  const olla = (cx, base, w = 26, h = 18, vapor = true) => `<rect x="${cx - w / 2}" y="${base - h}" width="${w}" height="${h}" rx="2" fill="#B0BEC5" stroke="#607D8B"/><rect x="${cx - w / 2 - 2}" y="${base - h - 2}" width="${w + 4}" height="3" rx="1" fill="#90A4AE"/><path d="M${cx - w / 2},${base - h + 4} h-4 v5 h4 M${cx + w / 2},${base - h + 4} h4 v5 h-4" stroke="#455A64" stroke-width="2" fill="none"/>` + (vapor ? vap(cx, base - h - 3) : '');
  // sartén: dir = 1 mango a la derecha, -1 a la izquierda
  const sarten = (cx, base, dir = 1, len = 20, s = 1) => `<g transform="translate(${cx},${base}) scale(${s})"><path d="M-13,-6 h26 l-3,6 h-20 z" fill="#37474F"/><line x1="${dir * 13}" y1="-5" x2="${dir * (13 + len)}" y2="-8" stroke="#263238" stroke-width="3.2" stroke-linecap="round"/></g>`;
  // cocina industrial de frente: x = borde izquierdo, w = ancho, fuegos = centros con llama
  const cocinaF = (x, w = 100, fuegos = []) => `<rect x="${x}" y="${MT}" width="${w}" height="${FL - MT}" fill="#90A4AE" stroke="#607D8B"/><rect x="${x + 8}" y="${MT + 16}" width="${w - 16}" height="${FL - MT - 22}" rx="2" fill="#78909C" stroke="#546E7A"/><rect x="${x + 16}" y="${MT + 22}" width="${w - 32}" height="12" rx="2" fill="#37474F"/><rect x="${x + 20}" y="${MT + 18}" width="${w - 40}" height="3" rx="1.5" fill="#CFD8DC"/>`
    + [...Array(Math.floor(w / 18))].map((_, i) => `<circle cx="${x + 12 + i * 18}" cy="${MT + 8}" r="3" fill="#263238"/>`).join('')
    + `<rect x="${x - 2}" y="${MT - 4}" width="${w + 4}" height="5" rx="1" fill="#37474F"/>` + fuegos.map(c => `<path d="M${c - 12},${MT - 4} v-3 M${c + 12},${MT - 4} v-3 M${c - 13},${MT - 7} h26" stroke="#212121" stroke-width="1.6"/>` + llama(c - 8, MT - 5, 6) + llama(c + 8, MT - 5, 6) + llama(c, MT - 5, 7)).join('');
  // cocina de perfil (la persona trabaja por la izquierda): x = frente, d = fondo
  const cocinaP = (x, d = 50, fuego = true) => `<rect x="${x + d}" y="${MT - 60}" width="5" height="${FL - MT + 60}" fill="#B0BEC5"/><rect x="${x}" y="${MT}" width="${d}" height="${FL - MT}" fill="#90A4AE" stroke="#607D8B"/><rect x="${x - 3}" y="${MT + 6}" width="3" height="5" fill="#263238"/><rect x="${x - 4}" y="${MT + 18}" width="4" height="22" rx="1.5" fill="#CFD8DC" stroke="#78909C" stroke-width=".8"/><rect x="${x - 2}" y="${MT - 4}" width="${d + 4}" height="5" rx="1" fill="#37474F"/>` + (fuego ? llama(x + d / 2 - 7, MT - 5, 6) + llama(x + d / 2 + 7, MT - 5, 6) : '');
  // freidora (vista de frente)
  const freidora = (x, w = 34) => `<rect x="${x}" y="${MT}" width="${w}" height="${FL - MT}" fill="#B0BEC5" stroke="#78909C"/><rect x="${x + 4}" y="${MT + 10}" width="${w - 8}" height="10" rx="2" fill="#37474F"/><circle cx="${x + 10}" cy="${MT + 15}" r="2" fill="#FF7043"/><rect x="${x + 2}" y="${MT - 4}" width="${w - 4}" height="5" fill="#FFB300" stroke="#8D6E00" stroke-width=".8"/>` + [0, 1, 2].map(i => `<circle class="h_co_bub" cx="${x + 8 + i * 9}" cy="${MT - 5}" r="1.6" fill="#FFE082" style="animation-delay:${i * .35}s"/>`).join('') + `<line x1="${x + w / 2}" y1="${MT - 2}" x2="${x + w / 2 + 12}" y2="${MT - 16}" stroke="#263238" stroke-width="2.4" stroke-linecap="round"/>`;
  // horno combinado de frente sobre su base; top = parte alta
  const horno = (x, top = 86, w = 48, h = 38, abierto = false) => `<rect x="${x + 4}" y="${top + h}" width="4" height="${FL - top - h}" fill="#90A4AE"/><rect x="${x + w - 8}" y="${top + h}" width="4" height="${FL - top - h}" fill="#90A4AE"/><rect x="${x + 4}" y="${FL - 18}" width="${w - 8}" height="4" fill="#B0BEC5"/><rect x="${x}" y="${top}" width="${w}" height="${h}" rx="2" fill="#CFD8DC" stroke="#78909C" stroke-width="1.2"/><rect x="${x + w - 11}" y="${top + 4}" width="7" height="${h - 8}" fill="#37474F"/><circle cx="${x + w - 7.5}" cy="${top + 12}" r="2" fill="#FF7043"/>`
    + (abierto ? `<rect x="${x + 4}" y="${top + 4}" width="${w - 18}" height="${h - 8}" fill="#3E2723"/>${[0, 1, 2].map(i => `<rect x="${x + 6}" y="${top + 11 + i * 9}" width="${w - 22}" height="2" fill="#8D6E63"/>`).join('')}<path d="M${x + 4},${top + 3} l-13,4 v${h - 14} l13,4 z" fill="#90A4AE" stroke="#607D8B"/>` : `<rect x="${x + 4}" y="${top + 4}" width="${w - 18}" height="${h - 8}" rx="2" fill="#455A64"/><rect x="${x + 8}" y="${top + 8}" width="${w - 26}" height="${h - 16}" rx="2" fill="#607D8B" opacity=".7"/><rect x="${x + w - 16}" y="${top + 8}" width="2.5" height="${h - 16}" fill="#ECEFF1"/>`);
  // cámara de frío (puerta vista desde la cocina)
  const puertaCamara = (x, w = 54) => `<rect x="${x - 4}" y="${FL - 112}" width="${w + 8}" height="112" fill="#ECEFF1" stroke="#B0BEC5"/><rect x="${x}" y="${FL - 106}" width="${w}" height="106" fill="#F5F7F8" stroke="#90A4AE" stroke-width="1.5"/><rect x="${x + w - 12}" y="${FL - 66}" width="6" height="22" rx="3" fill="#607D8B"/><rect x="${x + 10}" y="${FL - 96}" width="${w - 20}" height="12" rx="2" fill="#0E3962"/>` + T(x + w / 2, FL - 87, '2 °C', 8, '#81D4FA');
  // fondo: interior de la cámara de frío
  const camBg = () => `<rect width="320" height="200" fill="#E1F5FE"/>` + [0, 1, 2, 3, 4, 5, 6, 7].map(i => `<line x1="${i * 44}" y1="0" x2="${i * 44}" y2="165" stroke="#B3E5FC" stroke-width="2"/>`).join('') + `<path d="M0,0 h320 v8 q-20,6 -40,0 q-20,7 -40,0 q-20,6 -40,0 q-20,7 -40,0 q-20,6 -40,0 q-20,7 -40,0 q-20,6 -40,0 q-20,7 -40,0 z" fill="#FFFFFF" opacity=".9"/>`
