  const cae = q => Z(H.fondo.cocina(), meson(20, 150) + tabla(40, MT, 56) + verduras(48, MT - 5) + `<g class="h_co_fall"><g transform="rotate(64 178 122)">${knife(178, 122, 0, .55)}</g></g>` + `<ellipse cx="180" cy="167" rx="10" ry="2" fill="#000" opacity=".12"/>`
    + W(220, 165, C({ pose: 'stop', flip: true, face: 'worried' })) + (q ? '' : arr(232, 186, 268, 186, '#2E7D32', 3) + bubble(196, 22, '¡Lo dejo caer!', 112)));
  S.h_co_cor_cae = () => cae(false);
