  S.h_co_cor_guardar = () => Z(H.fondo.cocina(), `<rect x="12" y="104" width="136" height="70" rx="4" fill="#B0BEC5" stroke="#78909C" stroke-width="1.5"/><rect x="20" y="112" width="120" height="56" rx="3" fill="#4FC3F7" opacity=".55"/>`
    + [...Array(16)].map((_, i) => `<circle cx="${26 + (i * 23) % 112}" cy="${114 + (i * 7) % 18}" r="${4 + i % 3}" fill="#FFFFFF" opacity=".9"/>`).join('') + `<rect x="92" y="117" width="12" height="5" rx="2" fill="#263238" transform="rotate(-10 98 120)"/>` + brazo(60, 120, 30, 70, '#FFFFFF', 12) + puno(60, 124, .8) + aro(84, 124, 16) + badge(140, 26, false, 13)
    + divider() + iman(184, 52, 120) + knife(204, 62, 90, 1.1) + knifeChico(232, 62, 90, 1.1) + knifeSierra(258, 62, 90, 1) + knife(284, 62, 90, 1.1) + pill(244, 150, 'A la vista', '#2E7D32') + badge(300, 26, true, 13));
  S.h_co_cor_guante = () => { const id = 'h_co_m1'; return Z(H.fondo.cocina(), malla(id) + mesonG() + tablaG(10, 153, 140) + `<path d="M20,153 q30,-30 100,-16 q12,4 8,16 z" fill="#EF9A9A" stroke="#C62828"/>` + brazo(54, 126, 20, 80, '#FFFFFF', 13)
      + `<rect x="40" y="120" width="36" height="22" rx="10" fill="#B0BEC5" stroke="${OL}" stroke-width="1.2"/><rect x="40" y="120" width="36" height="22" rx="10" fill="url(#${id})"/>` + knife(112, 140, -8, 1.1) + pill(60, 46, 'Guante anticorte', '#1565C0') + linea(60, 66, 58, 116)
      + divider() + lata(200, 160, true) + abrelatas(232, 112) + pill(262, 46, 'Abrelatas', '#1565C0') + pill(212, 178, 'La tapa corta', '#D7262B')); };
  const vidrioEsc = q => Z(H.fondo.cocina(), meson(14, 96) + (q ? `<path d="M40,${MT} q0,-14 18,-14 h12 q18,0 18,14 z" fill="#A5D6A7" stroke="#2E7D32"/><circle cx="56" cy="${MT - 8}" r="3" fill="#E53935"/><circle cx="70" cy="${MT - 9}" r="3" fill="#E53935"/>` : `<rect x="34" y="${MT - 24}" width="40" height="24" fill="#C89B5E" stroke="#8D6E3F"/><rect x="38" y="${MT - 18}" width="32" height="10" fill="#FFFFFF"/>` + T(54, MT - 10, 'VIDRIO', 7, '#D7262B'))
    + vidrios(130, 172) + vidrios(160, 178) + (q ? W(250, 165, C({ pose: 'point', flip: true, face: 'worried', hair: true })) : pala(122, 182) + W(212, 165, C({ pose: 'bend', flip: true, hair: true })) + escoba(156, 176, 180, 144) + pill(236, 40, 'Escoba y pala', '#2E7D32')));
