  SI_CONT.temas.push({
    id: 'co_cortes', sec: 'cocina', emp: ['hotel'], title: 'Cuchillos y cortes en la cocina', thumb: 'h_co_cor_intro', mins: 15,
    learn: [
      { s: 'h_co_cor_intro', t: 'Los cortes, un riesgo de todos los días', x: 'En la cocina del hotel usamos cuchillos todo el día: para picar verduras, porcionar carnes y cortar pan y fiambre. Un corte en la mano puede dañar un <b>tendón o un nervio</b> y dejarte semanas sin trabajar. Casi todos se evitan con el <b>cuchillo correcto</b>, una <b>tabla firme</b>, buena <b>técnica</b> y orden. Esta charla complementa el procedimiento de <b>Trabajos en cocina</b> que recibiste.' },
      { s: 'h_co_cor_cuchillo', t: 'El cuchillo correcto y afilado', x: '<ul><li>Usa el cuchillo <b>adecuado para cada tarea</b>: uno grande para picar, uno chico para pelar y el de sierra para el pan.</li><li>Un cuchillo <b>afilado</b> corta con menos fuerza y resbala menos que uno sin filo.</li><li>Mango firme, limpio y seco, sin trizaduras.</li><li><b>Nunca</b> lo uses como palanca, como destornillador ni para abrir latas o cajas.</li></ul>' },
      { s: 'h_co_cor_tabla', t: 'Tabla firme sobre un paño húmedo', x: 'Una tabla que se desliza hace que el cuchillo se vaya hacia tu mano.<ul><li>Pon un <b>paño húmedo</b> o una base antideslizante <b>debajo de la tabla</b>.</li><li>Corta siempre sobre la tabla, nunca con el alimento en el aire o en la mano.</li><li>Apoya los alimentos redondos por su <b>cara plana</b>: córtalos primero por la mitad para que no rueden.</li><li>Tabla limpia y sin grasa.</li></ul>' },
      { s: 'h_co_cor_tecnica', t: 'Dedos en garra y filo lejos de ti', x: '<ul><li>La mano que sujeta va en <b>garra</b>: dedos recogidos y uñas hacia adentro. El costado del cuchillo se apoya en los nudillos, nunca en la punta de los dedos.</li><li>Corta con el filo <b>alejándose de tu cuerpo</b> y de tu otra mano.</li><li>No cortes conversando ni mirando a otro lado.</li><li>Deja espacio con quien trabaja a tu lado.</li></ul>', k: 'Dedos en garra y el filo siempre alejándose de tu mano y de tu cuerpo.' },
      { s: 'h_co_cor_cae', t: 'Si se cae, déjalo caer', x: 'El reflejo natural es atrapar lo que se cae. Con un cuchillo, ese reflejo termina en un <b>corte profundo</b> en la palma o en los dedos. <b>Nunca intentes atrapar un cuchillo que cae</b>: retira las manos y los pies, deja que llegue al suelo y recógelo del mango cuando esté quieto. Por eso en la cocina se usa calzado cerrado.', k: 'Nunca atrapes un cuchillo que cae: retírate y déjalo caer.' },
      { s: 'h_co_cor_guardar', t: 'Guardar, lavar y trasladar', x: '<ul><li>Si no lo usas, va en su <b>soporte, imán o cuchillero</b>, nunca en el borde del mesón ni tapado con comida.</li><li><b>Nunca lo dejes en el lavaplatos</b> con agua y espuma: no se ve y alguien mete la mano. Lávalo de inmediato, a la vista y con el filo hacia afuera.</li><li>Para trasladarlo, punta hacia abajo y pegado al cuerpo. Avisa "cuchillo" al pasar detrás de alguien.</li></ul>' },
      { s: 'h_co_cor_guante', t: 'Guante anticorte, abrelatas y mandolina', x: '<ul><li>En tareas de mucho corte, como deshuesar, filetear o limpiar el disco de la cortadora de fiambre, usa <b>guante anticorte</b> en la mano que sujeta, como indique tu jefatura.</li><li>Abre las latas con el <b>abrelatas</b>, nunca con cuchillo. La tapa corta: no la saques con los dedos.</li><li>Si usas mandolina, siempre con su <b>protector o empujador</b>.</li></ul>' },
      { s: 'h_co_cor_vidrio', t: 'Vidrios rotos y si te cortas', x: '<ul><li>Vaso o loza rota: <b>no la recojas con las manos</b>. Usa escoba y pala, y bótala envuelta en papel o en una caja cerrada y marcada.</li><li>Si se quebró cerca de alimentos, <b>bótalos</b>: puede haber trozos.</li><li>Si te cortas: presiona con un paño limpio, <b>avisa de inmediato</b> a tu jefatura y acude a la <b>ACHS</b>, aunque el corte parezca pequeño.</li></ul>' }
    ],
    quiz: [
      { s: 'h_co_cor_cuchillo', v: [
        { q: '¿Por qué es más seguro trabajar con un cuchillo afilado?', o: ['Porque corta con menos fuerza y resbala menos', 'Porque así no es necesario usar tabla', 'Porque se puede usar también como palanca', 'Porque permite cortar sin mirar'], w: 'Un cuchillo sin filo obliga a hacer más fuerza y resbala con más facilidad hacia la mano.' },
        { q: 'Necesitas abrir una lata de duraznos y no encuentras el abrelatas. ¿Qué haces?', o: ['Busco o pido el abrelatas; no la abro con cuchillo', 'La abro con la punta del cuchillo grande', 'La abro con un cuchillo sin filo, que es más seguro', 'Le pego con el mango del cuchillo hasta abrirla'], w: 'El cuchillo no es palanca ni abrelatas: se quiebra o resbala y la mano se va al filo.' },
        { q: 'Un cuchillo con el mango trizado se puede seguir usando si lo tomas con más fuerza.', vf: false, w: 'Falso. Un mango dañado se suelta o resbala y la mano se va al filo: se deja de usar y se pide cambio.' } ] },
      { s: 'h_co_cor_tabla', v: [
        { q: '¿Qué evita que la tabla se deslice sobre el mesón?', o: ['Un paño húmedo o una base antideslizante debajo', 'Sujetarla con el codo mientras cortas', 'Mojar la tabla por encima', 'Cortar más rápido para que no alcance a moverse'], w: 'El paño húmedo o la base antideslizante dejan la tabla firme: así el cuchillo no se desvía.' },
        { q: 'Vas a picar una cebolla entera, que rueda sobre la tabla. ¿Qué haces primero?', o: ['La corto por la mitad y la apoyo en su cara plana', 'La sujeto en el aire con la mano', 'La apoyo contra mi cuerpo para que no se mueva', 'La pico rápido antes de que ruede'], w: 'Apoyado en su cara plana, el alimento no rueda y el corte es controlado.' },
        { q: 'Para ir más rápido, se puede cortar el pan sosteniéndolo en la mano en vez de apoyarlo en la tabla.', vf: false, w: 'Falso. Siempre se corta sobre la tabla: con el alimento en la mano, el filo termina en tus dedos.' } ] },
      { s: 'h_co_cor_tecnica', v: [
        { q: '¿Cómo debe ir la mano que sujeta el alimento al picar?', o: ['En garra, con los dedos recogidos y las uñas hacia adentro', 'Estirada, con los dedos sobre el alimento', 'Con el pulgar adelante, guiando el corte', 'Lejos del alimento, sin sujetarlo'], w: 'Con los dedos en garra, el cuchillo se apoya en los nudillos y no alcanza la punta de los dedos.' },
        { q: 'Un compañero porciona carne tirando el cuchillo hacia su abdomen. ¿Qué le dices?', o: ['Que corte con el filo alejándose de su cuerpo', 'Que lo haga más rápido para cansarse menos', 'Que se ponga dos pares de guantes de látex', 'Nada, porque ya tiene experiencia'], w: 'Cortar hacia el cuerpo es una causa típica de cortes graves. Avisar es cuidarse entre todos.' },
        { q: '¿Contra qué parte de la mano se apoya el costado del cuchillo al picar?', o: ['Contra los nudillos de la mano en garra', 'Contra la punta de los dedos estirados', 'Contra la palma abierta', 'Contra el pulgar extendido'], w: 'Los nudillos guían el cuchillo; las puntas de los dedos quedan recogidas, lejos del filo.' } ] },
      { s: 'h_co_cor_cae_q', v: [
        { q: 'Se te resbala el cuchillo del mesón. ¿Qué haces?', o: ['Retiro manos y pies y lo dejo caer', 'Lo atrapo rápido en el aire', 'Lo detengo con el pie', 'Intento agarrarlo del mango mientras cae'], w: 'Atrapar un cuchillo que cae termina en un corte profundo. Se deja caer y se recoge del mango.' },
        { q: 'Un cuchillo cayó al piso. ¿Cuándo y cómo lo recoges?', o: ['Cuando está quieto, tomándolo del mango', 'Mientras rebota, para que no se ensucie', 'Empujándolo con el pie hacia el mesón', 'Tomándolo de la hoja, que es más fácil'], w: 'Se espera a que quede quieto y se toma por el mango.' },
        { q: 'Si un cuchillo se cae, lo correcto es atraparlo antes de que llegue al piso.', vf: false, w: 'Falso. Nunca se atrapa un cuchillo que cae: retiras manos y pies y lo dejas caer.' } ] },
      { s: 'h_co_cor_guardar', v: [
        { q: '¿Por qué nunca se deja un cuchillo dentro del lavaplatos con agua y espuma?', o: ['Porque no se ve y alguien puede meter la mano y cortarse', 'Porque el agua le quita el filo', 'Porque el detergente daña el mango', 'Porque ocupa espacio para la loza'], w: 'Un cuchillo escondido bajo la espuma es una trampa para quien mete la mano.' },
        { q: 'Terminaste de picar y vas a la bodega. ¿Dónde dejas el cuchillo?', o: ['En su soporte, imán o cuchillero', 'En el borde del mesón', 'Debajo de las verduras picadas', 'En el bolsillo de la pechera'], w: 'El cuchillo que no se usa va a la vista, en su soporte, imán o cuchillero.' },
        { q: 'Tienes que llevar un cuchillo al otro lado de la cocina. ¿Cómo lo haces?', o: ['Con la punta hacia abajo, pegado al cuerpo y avisando "cuchillo"', 'Con la punta hacia adelante para ver por dónde va', 'Dentro del bolsillo de la pechera', 'Moviendo el brazo para abrirme paso'], w: 'Punta abajo y pegado al cuerpo: si chocas o resbalas, no hieres a nadie.' } ] },
      { s: 'h_co_cor_guante', v: [
        { q: '¿En qué tarea corresponde usar guante anticorte, como indique tu jefatura?', o: ['Al deshuesar o al limpiar el disco de la cortadora', 'Al servir café en el comedor', 'Al lavar ollas con agua caliente', 'Al sacar bandejas del horno'], w: 'El guante anticorte se usa en tareas de mucho corte, como deshuesar, filetear o limpiar el disco.' },
        { q: '¿En qué mano se usa el guante anticorte al filetear?', o: ['En la mano que sujeta el alimento', 'En la mano que toma el cuchillo', 'En ninguna, porque estorba', 'Solo en la mano más hábil'], w: 'La mano que sujeta queda cerca del filo: por eso lleva el guante anticorte.' },
        { q: 'Con el guante anticorte puesto ya no importa hacia dónde muevas el filo.', vf: false, w: 'Falso. El guante reduce el daño, pero no reemplaza la técnica: el filo siempre se aleja de ti.' } ] },
      { s: 'h_co_cor_vidrio_q', v: [
        { q: 'Se quebró un vaso en el piso de la cocina. ¿Cómo recoges los trozos?', o: ['Con escoba y pala, nunca con las manos', 'Con las manos, con mucho cuidado', 'Con un paño mojado tomado con la mano', 'Empujándolos con el pie bajo el mesón'], w: 'El vidrio se recoge con escoba y pala; con las manos, los trozos chicos cortan.' },
        { q: 'Se quebró una fuente de vidrio junto a una ensalada lista. ¿Qué haces con la ensalada?', o: ['La boto, porque puede tener trozos de vidrio', 'La reviso a la vista y la sirvo', 'Le saco los trozos grandes y la sirvo', 'La lavo y la vuelvo a servir'], w: 'Los trozos de vidrio pueden ser invisibles: el alimento cercano se bota.' },
        { q: '¿Cómo se bota el vidrio roto?', o: ['Envuelto en papel o en una caja cerrada y marcada', 'Suelto en la bolsa de basura común', 'En el lavaplatos, con el agua', 'En el basurero del comedor'], w: 'Envuelto o en caja marcada, nadie se corta al sacar la basura.' } ] },
      { s: 'h_co_cor_herida', v: [
        { q: 'Te hiciste un corte pequeño en un dedo trabajando. ¿Qué corresponde?', o: ['Presionar con un paño limpio y avisar de inmediato a la jefatura', 'Ponerme cinta y seguir sin avisar', 'Esperar el final del turno para avisar', 'Lavarlo y no decir nada si deja de sangrar'], w: 'Todo corte se avisa de inmediato: se atiende en la ACHS por el seguro de la Ley 16.744.' },
        { q: '¿Dónde se atiende un corte que te hiciste trabajando en la cocina?', o: ['En la ACHS, avisando de inmediato a la jefatura', 'En mi casa, si no es profundo', 'En el consultorio, por mi cuenta', 'En ninguna parte, si dejó de sangrar'], w: 'Los accidentes del trabajo se atienden en la ACHS.' },
        { q: 'Un corte pequeño en el trabajo no es necesario avisarlo si deja de sangrar.', vf: false, w: 'Falso. Todo corte se avisa de inmediato, aunque parezca pequeño, y se atiende en la ACHS.' } ] }
    ]
  });

  // =====================================================================
  // 2. QUEMADURAS EN LA COCINA
