  const M = o => Object.assign({ area: 'comedor', hair: true }, o || {});
  const HU = (o, i = 0) => Object.assign({ area: 'general', shirt: ['#C62828', '#6A1B9A', '#2E7D32', '#EF6C00'][i % 4], pants: ['#5D4037', '#37474F', '#1A237E', '#455A64'][i % 4] }, o || {});
  const pl = (pts, c, w) => `<polyline points="${pts.map(p => p.join(',')).join(' ')}" fill="none" stroke="${OL}" stroke-width="${w + 2.4}" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${pts.map(p => p.join(',')).join(' ')}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
  // persona sentada (pies en el piso): cadera en (x, y). Modelo San Ignacio.
  function sitP(x, y, o = {}) {
    const k = o.s || 1, bad = o.bad, shirt = o.shirt || '#90CAF9', pants = o.pants || '#37474F', fx = o.flip ? -1 : 1;
    const P = (a, b) => [+(x + a * k * fx).toFixed(1), +(y + b * k).toFixed(1)];
    const hip = P(0, 0), kn = P(22, 0), ft = o.feetUp ? P(26, 14) : P(24, 22), nk = bad ? P(12, -24) : P(2, -27), hd = bad ? P(20, -31) : P(4, -38);
    const el = o.elbow ? P(o.elbow[0], o.elbow[1]) : (bad ? P(16, -10) : P(5, -12)), hn = o.hand ? P(o.hand[0], o.hand[1]) : (bad ? P(30, -12) : P(22, -12));
    let g = pl([hip, kn, ft], pants, 8 * k) + `<rect x="${ft[0] - (fx > 0 ? 4 : 8) * k}" y="${ft[1] - 3 * k}" width="${12 * k}" height="${5 * k}" rx="${2 * k}" fill="#3E2723"/>`;
    g += pl(bad ? [hip, P(8, -14), nk] : [hip, P(-2, -14), nk], shirt, 14 * k);
    g += pl([nk, el, hn], shirt, 6 * k) + `<circle cx="${hn[0]}" cy="${hn[1]}" r="${3.8 * k}" fill="${SK}" stroke="${OL}" stroke-width="1"/>`;
    g += `<line x1="${nk[0]}" y1="${nk[1]}" x2="${hd[0]}" y2="${hd[1] + 6 * k}" stroke="${SK}" stroke-width="${5 * k}"/><circle cx="${hd[0]}" cy="${hd[1]}" r="${9.5 * k}" fill="${SK}" stroke="${OL}" stroke-width="1.2"/>`;
    if (o.longHair) g += `<path d="M${hd[0] - 8 * k * fx},${hd[1] - 2 * k} q${-5 * k * fx},${14 * k} ${-2 * k * fx},${22 * k}" stroke="${o.hair || '#4E342E'}" stroke-width="${6 * k}" fill="none" stroke-linecap="round"/>`;
    g += `<path d="M${hd[0] - 9.5 * k},${hd[1] - 1 * k} Q${hd[0] - 8 * k * fx},${hd[1] - 12 * k} ${hd[0] + 2 * k * fx},${hd[1] - 10 * k} Q${hd[0] - 2 * k * fx},${hd[1] - 5 * k} ${hd[0] - 9.5 * k * fx},${hd[1] - 1 * k}Z" fill="${o.hair || '#4E342E'}"/>`;
    g += `<circle cx="${hd[0] + 4 * k * fx}" cy="${hd[1] - .5 * k}" r="${1.3 * k}" fill="${OL}"/><path d="M${hd[0] + 3 * k * fx},${hd[1] + 4.5 * k} q${2 * k * fx},${o.face === 'pain' ? -1.5 * k : 1.5 * k} ${4 * k * fx},0" stroke="${OL}" stroke-width="1" fill="none"/>`;
    return g;
  }
  const mesaC = (x, w = 70) => `<rect x="${x + 6}" y="129" width="4" height="36" fill="#6D4C41"/><rect x="${x + w - 10}" y="129" width="4" height="36" fill="#6D4C41"/><rect x="${x}" y="125" width="${w}" height="4" fill="#FFFFFF" stroke="#CFD8DC"/><path d="M${x},129 h${w} v10 q${-w / 4},4 ${-w / 2},0 q${-w / 4},4 ${-w / 2},0 z" fill="#FAFAFA" stroke="#E0E0E0"/>`;
  const sillaC = (x, flip) => { const b = flip ? x + 10 : x - 12; return `<rect x="${x - 12}" y="139" width="22" height="4" fill="#8D6E63"/><rect x="${x - 10}" y="143" width="3" height="22" fill="#6D4C41"/><rect x="${x + 5}" y="143" width="3" height="22" fill="#6D4C41"/><rect x="${b}" y="104" width="3" height="37" fill="#6D4C41"/>`; };
  const taza = (x, y, c = '#FFFFFF') => `<path d="M${x - 5},${y - 8} h10 l-1,8 h-8 z" fill="${c}" stroke="#90A4AE" stroke-width=".8"/><path d="M${x + 5},${y - 6} q4,1 0,4" stroke="#90A4AE" fill="none"/><ellipse cx="${x}" cy="${y}" rx="7" ry="1.5" fill="#FFFFFF" stroke="#B0BEC5" stroke-width=".6"/>`;
  const plato = (x, y) => `<ellipse cx="${x}" cy="${y}" rx="9" ry="2.2" fill="#FFFFFF" stroke="#B0BEC5"/>`;
  const termo = (x, base, s = 1) => `<rect x="${x}" y="${base - 26 * s}" width="${12 * s}" height="${26 * s}" rx="${3 * s}" fill="#B0BEC5" stroke="#607D8B"/><rect x="${x + 2 * s}" y="${base - 31 * s}" width="${8 * s}" height="${5 * s}" rx="1" fill="#263238"/><rect x="${x + 12 * s}" y="${base - 22 * s}" width="${4 * s}" height="${3 * s}" fill="#263238"/>`;
  const cafetera = (x, base) => `<rect x="${x}" y="${base - 30}" width="24" height="30" rx="2" fill="#37474F"/><rect x="${x + 2}" y="${base - 28}" width="20" height="6" fill="#263238"/><circle cx="${x + 18}" cy="${base - 25}" r="1.6" fill="#43A047"/><path d="M${x + 6},${base - 13} h11 l-1,12 h-9 z" fill="#B3E5FC" opacity=".8" stroke="#607D8B"/><rect x="${x + 7}" y="${base - 7}" width="9" height="6" fill="#5D4037"/>` + vap(x + 12, base - 31, .7, '#CFD8DC');
  const fuente = (x, base, c = '#FFB300') => `<path d="M${x - 12},${base - 7} h24 l-3,7 h-18 z" fill="#FFFFFF" stroke="#B0BEC5"/>` + [0, 1, 2].map(i => `<circle cx="${x - 6 + i * 6}" cy="${base - 9}" r="3.4" fill="${c}"/>`).join('');
  const buffet = (x, w = 110) => mesaC(x, w) + termo(x + 8, 125) + termo(x + 24, 125) + cafetera(x + 44, 125) + fuente(x + 84, 125, '#E53935') + (w > 110 ? fuente(x + 110, 125, '#FFB300') : '');
  const bandejaM = (x, y, n = 2, alto) => `<rect x="${x}" y="${y}" width="32" height="3" rx="1.5" fill="#5D4037"/>` + (alto ? [...Array(7)].map((_, i) => plato(x + 16, y - 2 - i * 4)).join('') + taza(x + 7, y - 30) + taza(x + 24, y - 30) + taza(x + 16, y - 38) : [...Array(n)].map((_, i) => taza(x + 10 + i * 12, y)).join(''));
  const carroS = (x, flip, carga = true) => { const d = flip ? -1 : 1, x2 = x + d * 54; const a = Math.min(x, x2); return `<rect x="${x - 2 * d}" y="${FL - 62}" width="4" height="${62 - 8}" fill="#78909C"/><rect x="${a}" y="${FL - 46}" width="54" height="4" fill="#B0BEC5" stroke="#78909C"/><rect x="${a}" y="${FL - 20}" width="54" height="4" fill="#B0BEC5" stroke="#78909C"/><rect x="${x2 - 2 * d}" y="${FL - 46}" width="3" height="40" fill="#78909C"/>` + [a + 6, a + 48].map(cx => `<circle cx="${cx}" cy="${FL - 4}" r="4" fill="#263238"/>`).join('')
    + (carga ? `<rect x="${a + 4}" y="${FL - 34}" width="44" height="14" rx="2" fill="#1E88E5" stroke="#0D47A1"/>` + [0, 1, 2].map(i => plato(a + 14 + i * 13, FL - 47) + plato(a + 14 + i * 13, FL - 50)).join('') + taza(a + 22, FL - 52) : ''); };
  const huesped = (x, i, o) => W(x, 165, HU(o, i));
  const trapero = (x, y, hx, hy) => `<line x1="${x}" y1="${y}" x2="${hx}" y2="${hy}" stroke="#90A4AE" stroke-width="3"/><path d="M${x - 12},${y} h24 l-2,6 h-20 z" fill="#ECEFF1" stroke="#90A4AE"/>`;
