    + termo(128, 125) + termo(144, 125) + cafetera(160, 125) + W(106, 165, M({ pose: 'carry', flip: true })) + pill(150, 40, 'Lejos del borde', '#2E7D32') + linea(150, 60, 150, 90, '#2E7D32')
