  const B = o => Object.assign({ area: 'bodega', hair: true }, o || {});
  const bodBg = () => `<rect width="320" height="165" fill="#E0E0E0"/><rect y="0" width="320" height="14" fill="#CFD8DC"/><rect y="165" width="320" height="35" fill="#9E9E9E"/><rect y="165" width="320" height="3" fill="#000" opacity=".08"/>` + [0, 1, 2, 3, 4, 5, 6, 7].map(i => `<line x1="${i * 46}" y1="165" x2="${i * 46 - 22}" y2="200" stroke="#8A8A8A" stroke-width="1.3"/>`).join('');
  // estantería de 2 metros: repisas en 65, 98, 131 y la base en 160
  const estante = (x, w = 90, firme = true) => `<rect x="${x}" y="62" width="4" height="${FL - 62}" fill="#607D8B"/><rect x="${x + w - 4}" y="62" width="4" height="${FL - 62}" fill="#607D8B"/>` + [65, 98, 131, 158].map(y => `<rect x="${x}" y="${y}" width="${w}" height="4" fill="#78909C"/>`).join('') + (firme ? `<rect x="${x + w - 2}" y="70" width="8" height="5" fill="#455A64"/>` : '');
  const caja = (x, base, w = 26, h = 18, c = '#C89B5E', t = '') => `<rect x="${x}" y="${base - h}" width="${w}" height="${h}" rx="1" fill="${c}" stroke="#8D6E3F"/><rect x="${x + w / 2 - 2}" y="${base - h}" width="4" height="${h}" fill="#E0C08A" opacity=".75"/>` + (t ? `<rect x="${x + 3}" y="${base - h / 2 - 5}" width="${w - 6}" height="10" fill="#FFFFFF"/>` + T(x + w / 2, base - h / 2 + 3, t, Math.min(7, (w - 8) / (t.length * .62)).toFixed(1), '#263238') : '');
  const saco = (x, base, w = 30, h = 22, t = 'HARINA') => `<path d="M${x},${base} v${-h + 6} q0,-6 6,-6 h${w - 12} q6,0 6,6 v${h - 6} z" fill="#F5E6C8" stroke="#A1887F"/>` + T(x + w / 2, base - h / 2 + 2, t, 6, '#6D4C41') + T(x + w / 2, base - h / 2 + 9, '25 kilos', 5, '#6D4C41', 'middle', 'normal');
  const liviano = (x, base) => `<rect x="${x}" y="${base - 12}" width="16" height="12" fill="#FFFFFF" stroke="#B0BEC5"/><rect x="${x + 18}" y="${base - 10}" width="16" height="10" fill="#E3F2FD" stroke="#90CAF9"/>`;
  const raton = (x, y, s = 1, flip) => `<g transform="translate(${x},${y}) scale(${flip ? -s : s},${s})"><path d="M-8,0 q-26,-2 -34,-10" stroke="#8D6E63" stroke-width="1.4" fill="none"/><ellipse cx="0" cy="-5" rx="10" ry="6" fill="#8D6E63"/><circle cx="9" cy="-7" r="4.5" fill="#8D6E63"/><circle cx="7" cy="-11" r="2.6" fill="#BCAAA4"/><circle cx="12" cy="-8" r="1" fill="#212121"/><path d="M13,-6 l4,-1 M13,-5 l4,1" stroke="#5D4037" stroke-width=".6"/></g>`;
  const fecas = (x, y) => [0, 1, 2, 3, 4, 5].map(i => `<ellipse cx="${x + (i * 7) % 30}" cy="${y + (i % 3) * 2}" rx="1.6" ry="1" fill="#3E2723"/>`).join('');
  const carroP = (x, carga = true) => `<rect x="${x}" y="${FL - 12}" width="64" height="5" fill="#1565C0" stroke="#0D47A1"/><rect x="${x - 2}" y="${FL - 58}" width="4" height="50" fill="#455A64"/><rect x="${x - 6}" y="${FL - 60}" width="10" height="4" rx="2" fill="#263238"/>` + [x + 6, x + 56].map(c => `<circle cx="${c}" cy="${FL - 4}" r="4" fill="#263238"/>`).join('')
    + (carga ? caja(x + 4, FL - 12, 28, 20, '#A1887F', 'BEBIDAS') + caja(x + 34, FL - 12, 26, 20, '#A1887F', 'BEBIDAS') + caja(x + 8, FL - 32, 24, 14) + caja(x + 34, FL - 32, 22, 12, '#D7CCC8') : '');
  const hds = (x, y) => `<rect x="${x}" y="${y}" width="26" height="34" rx="2" fill="#FFFFFF" stroke="#90A4AE"/><rect x="${x}" y="${y}" width="26" height="9" rx="2" fill="#1565C0"/>` + T(x + 13, y + 7.5, 'HDS', 7, '#FFFFFF') + [0, 1, 2].map(i => `<rect x="${x + 4}" y="${y + 14 + i * 6}" width="${18 - i * 4}" height="2" fill="#B0BEC5"/>`).join('');
  const ampolleta = (x, y, ok = true) => `<line x1="${x}" y1="0" x2="${x}" y2="${y - 6}" stroke="#455A64" stroke-width="1.5"/><path d="M${x - 10},${y} h20 l-4,-6 h-12 z" fill="#455A64"/><circle cx="${x}" cy="${y + 4}" r="4" fill="${ok ? '#FFF59D' : '#9E9E9E'}"/>` + (ok ? `<path d="M${x - 9},${y + 2} L${x - 46},${FL} H${x + 46} L${x + 9},${y + 2} z" fill="#FFF59D" opacity=".22"/>` : '');
  const salida = (x, y) => `<rect x="${x}" y="${y}" width="46" height="16" rx="2" fill="#2E7D32"/>` + T(x + 23, y + 11.5, 'SALIDA', 9, '#FFFFFF');
  const pulverizador = (x, y) => `<path d="M${x},${y} h10 v-14 h-10 z" fill="#4FC3F7" stroke="#0277BD"/><rect x="${x + 2}" y="${y - 20}" width="6" height="6" fill="#263238"/><path d="M${x + 8},${y - 18} h6" stroke="#263238" stroke-width="2"/>` + `<g class="h_co_bl"><path d="M${x + 16},${y - 18} l18,16 M${x + 16},${y - 18} l22,8 M${x + 16},${y - 18} l12,20" stroke="#B3E5FC" stroke-width="2" stroke-dasharray="2 3"/></g>`;
