  SI_CONT.temas.push({
    id: 'bo_bodega', sec: 'bodega', emp: ['hotel'], title: 'Bodega: almacenamiento seguro y recepción de mercadería', thumb: 'h_bo_intro', mins: 15,
    learn: [
      { s: 'h_bo_intro', t: 'La bodega del hotel', x: 'En la bodega se guardan alimentos, bebidas, artículos de aseo y otros insumos del hotel. Aquí los riesgos son <b>golpes por objetos que caen</b>, <b>caídas</b> al subir a buscar algo, <b>lesiones de espalda</b> por cargar cajas y sacos, contacto con <b>químicos</b> y la presencia de <b>roedores</b>. Una bodega ordenada es una bodega segura, y además se trabaja más rápido.' },
      { s: 'h_bo_pesado', t: 'Lo pesado abajo', x: '<ul><li><b>Lo pesado abajo</b>: sacos, bidones, cajas de bebidas y conservas, en las repisas bajas, entre las rodillas y la cintura.</li><li><b>Lo liviano arriba</b>: servilletas, envases livianos, cajas vacías.</li><li>No sobrecargues las repisas ni dejes cajas <b>sobresaliendo</b> del borde.</li><li>Lo que se usa todos los días, a la altura más cómoda.</li></ul>', k: 'Lo pesado abajo, lo liviano arriba y nada sobresaliendo.' },
      { s: 'h_bo_estante', t: 'Estanterías firmes: nunca trepes', x: '<ul><li>Las estanterías deben estar <b>firmes y ancladas</b> al muro o al piso. Si una se mueve, se dobla o le falta una repisa, <b>avisa a mantención</b> y no la cargues más.</li><li><b>Nunca trepes</b> por las repisas ni te subas a cajas, sillas o bidones: la estantería se puede volcar encima tuyo.</li><li>Para alcanzar lo alto, usa la <b>escala</b>.</li></ul>', k: 'Nunca trepes por una estantería: usa la escala.' },
      { s: 'h_bo_escala', t: 'Uso correcto de la escala', x: '<ul><li>Revísala antes de usarla: peldaños firmes, patas con sus gomas, sin trizaduras.</li><li>Ábrela completa, con el <b>seguro trabado</b>, sobre piso firme y seco.</li><li>Sube y baja <b>de frente</b>, con <b>tres puntos de apoyo</b>: dos pies y una mano.</li><li>No te pares en los dos últimos peldaños ni te estires hacia los lados: baja y mueve la escala.</li><li>No subas con cargas pesadas en las manos.</li></ul>' },
      { s: 'h_bo_recepcion', t: 'Recepción de mercadería', x: '<ul><li>Antes de levantar una caja del proveedor, <b>prueba su peso</b> moviéndola un poco.</li><li>Levanta con las <b>piernas</b>, la espalda recta y la carga pegada al cuerpo. Si pesa mucho, pide ayuda o usa el <b>carro</b>.</li><li>La ley fija un máximo de <b>25 kilos</b> para cargar a mano, y de 20 kilos para las mujeres.</li><li>Abre las cajas con cuchillo cartonero <b>retráctil</b>, cortando hacia afuera.</li></ul>' },
      { s: 'h_bo_quimicos', t: 'Químicos separados de los alimentos', x: '<ul><li>Los productos de aseo y químicos se guardan en un <b>estante o sector aparte</b>, lejos de los alimentos y nunca encima de ellos.</li><li>Siempre en su <b>envase original y rotulado</b>. Nunca en botellas de bebida.</li><li>Los químicos, en las repisas bajas y con la tapa cerrada.</li><li>Ten a mano la <b>HDS</b> de cada producto.</li><li>Si algo se derrama, avisa y límpialo como indica la HDS.</li></ul>', k: 'Los químicos van aparte de los alimentos y en su envase original.' },
      { s: 'h_bo_roedores', t: 'Roedores y hantavirus', x: 'El hotel está rodeado de parque y bosque: los ratones pueden entrar a la bodega. El <b>hantavirus</b> se contagia al respirar polvo con orina o fecas del ratón colilargo.<ul><li>Si la bodega estuvo cerrada, <b>ventila al menos 30 minutos</b> antes de entrar.</li><li><b>Nunca barras en seco</b>: humedece con agua con cloro y usa mascarilla y guantes.</li><li>Si ves fecas o ratones, avisa a tu jefatura.</li></ul>' },
      { s: 'h_bo_orden', t: 'Orden e iluminación', x: '<ul><li>Pasillos <b>despejados</b>: nada en el piso, ni cajas ni bidones.</li><li>Las cajas vacías y los cartones, al reciclaje: estorban y además atraen roedores.</li><li>Alimentos en envases cerrados y sobre repisas, no en el piso.</li><li>La bodega debe tener <b>buena iluminación</b>: si una ampolleta está quemada, avisa a mantención.</li><li>Extintor y salida siempre sin obstáculos.</li></ul>' }
    ],
    quiz: [
      { s: 'h_bo_pesado', v: [
        { q: '¿Dónde se guardan los sacos de harina y los bidones?', o: ['En las repisas bajas', 'En la repisa más alta', 'Encima de las cajas livianas', 'En el pasillo, para tenerlos a mano'], w: 'Lo pesado abajo: si se cae, no te golpea la cabeza, y se levanta con menos esfuerzo.' },
        { q: '¿Qué va en las repisas altas de la bodega?', o: ['Lo liviano, como servilletas o envases vacíos', 'Las cajas de bebidas', 'Los bidones de cloro', 'Los sacos de azúcar'], w: 'Arriba solo lo liviano.' },
        { q: 'Se pueden dejar cajas sobresaliendo del borde de la repisa si quedan bien apoyadas al fondo.', vf: false, w: 'Falso. Lo que sobresale se engancha, se cae y golpea.' } ] },
      { s: 'h_bo_estante_q', v: [
        { q: 'Necesitas una caja de la repisa más alta y la escala está en otro lado. ¿Qué haces?', o: ['Voy a buscar la escala', 'Trepo por las repisas de la estantería', 'Me subo a un bidón', 'Me subo a una silla con ruedas'], w: 'Nunca se trepa ni se sube a bidones o sillas: se usa la escala.' },
        { q: 'Ves que una estantería se mueve y está suelta del muro. ¿Qué haces?', o: ['Aviso a mantención y no la cargo más', 'La sigo usando con menos peso arriba', 'La empujo contra el muro y sigo', 'Me subo para afirmarla'], w: 'Una estantería suelta se puede volcar: se avisa a mantención.' },
        { q: 'Si la estantería es firme, se puede trepar por las repisas para alcanzar algo rápido.', vf: false, w: 'Falso. Nunca se trepa por una estantería: se puede volcar o puedes caer.' } ] },
      { s: 'h_bo_escala', v: [
        { q: '¿Cómo se sube correctamente una escala?', o: ['De frente, con tres puntos de apoyo', 'De espaldas, para ver lo que hay arriba', 'Con una caja en cada mano', 'Saltando el primer peldaño'], w: 'De frente y con dos pies y una mano siempre apoyados.' },
        { q: 'Desde la escala no alcanzas una caja que está a un lado. ¿Qué haces?', o: ['Bajo, muevo la escala y vuelvo a subir', 'Me estiro hacia el lado', 'Me paro en el último peldaño', 'Me apoyo en la estantería para alcanzarla'], w: 'Estirarse saca tu cuerpo de la escala y la vuelca.' },
        { q: '¿Cómo debe quedar la escala de tijera antes de subir?', o: ['Abierta completa, con el seguro trabado y en piso firme', 'Medio abierta y apoyada en la estantería', 'Cerrada y apoyada contra el muro', 'Sobre un cajón para alcanzar más alto'], w: 'Abierta, trabada y en piso firme y seco.' } ] },
      { s: 'h_bo_recepcion', v: [
        { q: 'Llega una caja grande del proveedor. ¿Qué haces antes de levantarla?', o: ['Pruebo su peso moviéndola un poco', 'La levanto de un tirón', 'Le pido al proveedor que la tire al piso', 'La arrastro con el pie'], w: 'Probar el peso te dice si necesitas ayuda o el carro.' },
        { q: '¿Cuál es el peso máximo que la ley permite cargar a mano a un hombre?', o: ['25 kilos', '50 kilos', '35 kilos', '40 kilos'], w: 'La ley fija 25 kilos para hombres y 20 kilos para mujeres.' },
        { q: '¿Cómo abres las cajas de los proveedores?', o: ['Con cuchillo cartonero retráctil, cortando hacia afuera', 'Con un cuchillo de la cocina', 'Cortando hacia mi cuerpo para controlar mejor', 'Rompiendo la cinta con las llaves'], w: 'El cartonero retráctil esconde la hoja al soltarlo; se corta lejos del cuerpo.' } ] },
      { s: 'h_bo_carro', v: [
        { q: 'Tienes que trasladar seis cajas de bebidas. ¿Qué haces?', o: ['Uso el carro o pido ayuda', 'Las llevo apiladas en mis brazos de una vez', 'Las arrastro por el piso', 'Las lanzo de a una desde la puerta'], w: 'Con varias cajas o carga pesada se usa el carro o se pide ayuda.' },
        { q: 'Al terminar de descargar, ¿dónde quedan las cajas?', o: ['Guardadas en su lugar, sin dejarlas en pasillos ni puertas', 'En el pasillo, para ordenarlas mañana', 'Frente a la salida', 'Junto al extintor'], w: 'Los pasillos, las puertas y el extintor siempre quedan despejados.' },
        { q: 'Se puede dejar mercadería en el pasillo de la bodega para ordenarla otro día.', vf: false, w: 'Falso. Los pasillos van despejados: lo que queda en el piso hace tropezar.' } ] },
      { s: 'h_bo_quimicos', v: [
        { q: '¿Dónde se guarda el cloro en la bodega?', o: ['En un sector aparte, lejos de los alimentos y nunca encima', 'En la repisa sobre el arroz', 'Junto a las bebidas', 'En cualquier repisa libre'], w: 'Un derrame de cloro sobre alimentos los contamina: los químicos van aparte.' },
        { q: 'Sobró un poco de desengrasante. ¿Dónde lo guardas?', o: ['En su envase original y rotulado', 'En una botella de bebida vacía', 'En un vaso tapado con plástico', 'En un frasco sin etiqueta'], w: 'En una botella de bebida alguien lo puede tomar por error.' },
        { q: '¿Qué documento explica cómo guardar un químico y qué hacer si se derrama?', o: ['La hoja de datos de seguridad, o HDS', 'La factura del proveedor', 'La guía de despacho', 'El menú del día'], w: 'La HDS indica almacenamiento, EPP y qué hacer ante un derrame.' } ] },
      { s: 'h_bo_roedores', v: [
        { q: 'La bodega estuvo cerrada varias semanas. ¿Qué haces antes de entrar?', o: ['Abro puertas y ventanas y ventilo al menos 30 minutos', 'Entro de inmediato y barro', 'Entro con un ventilador encendido para limpiar', 'Cierro todo para que no entre polvo'], w: 'Ventilar renueva el aire y baja el polvo que puede tener el virus.' },
        { q: 'Encuentras fecas de ratón en una repisa. ¿Cómo las limpias?', o: ['Humedezco con agua con cloro, con mascarilla y guantes', 'Las barro en seco', 'Las soplo', 'Las recojo con la mano'], w: 'Barrer en seco levanta el polvo con virus. Se humedece con agua con cloro.' },
        { q: '¿Cómo se contagia el hantavirus?', o: ['Al respirar polvo con orina o fecas de ratón', 'Por la picadura de un zancudo', 'Por tomar agua de la llave', 'Por el frío de la bodega'], w: 'El virus está en la orina y las fecas del ratón colilargo, que se mezclan con el polvo.' } ] },
      { s: 'h_bo_orden', v: [
        { q: '¿Qué haces con las cajas vacías y los cartones en la bodega?', o: ['Los saco al reciclaje: estorban y atraen roedores', 'Los apilo en el pasillo', 'Los guardo bajo las repisas para después', 'Los dejo frente al extintor'], w: 'El cartón acumulado estorba y da refugio a los roedores.' },
        { q: 'Una ampolleta de la bodega está quemada. ¿Qué corresponde?', o: ['Avisar a mantención', 'Trabajar con la luz del celular sin avisar', 'Cambiarla subiéndome a una caja', 'Dejarla así, porque igual se ve algo'], w: 'Con poca luz no se ven los obstáculos ni las etiquetas: se avisa a mantención.' },
        { q: 'Los alimentos se pueden guardar en el piso de la bodega si están en sacos cerrados.', vf: false, w: 'Falso. Los alimentos van sobre repisas, no en el piso.' } ] }
    ]
  });

