  const mesonR = (x, w, top = 122) => `<rect x="${x}" y="${top + 6}" width="${w}" height="${FL - top - 6}" fill="#8D6E63" stroke="#5D4037"/><rect x="${x}" y="${top + 14}" width="${w}" height="10" fill="#0E3962"/><rect x="${x}" y="${top + 24}" width="${w}" height="2" fill="#D4A537"/><rect x="${x - 4}" y="${top}" width="${w + 8}" height="7" rx="1" fill="#5D4037"/>`;
  const pantallaR = (x, top = 122) => `<rect x="${x}" y="${top - 26}" width="5" height="24" rx="1" fill="#263238"/><rect x="${x + 1}" y="${top - 3}" width="10" height="3" fill="#263238"/>`;
  const enojo = (x, y) => `<g class="h_co_bl"><path d="M${x - 4},${y - 4} l4,4 M${x + 4},${y - 4} l-4,4 M${x - 4},${y + 4} l4,-4 M${x + 4},${y + 4} l-4,-4" stroke="#D7262B" stroke-width="2.4" stroke-linecap="round"/></g>`;
  const maleta = (x, base, w = 20, h = 28, c = '#C62828') => `<rect x="${x}" y="${base - h - 2}" width="${w}" height="${h}" rx="3" fill="${c}" stroke="#263238" stroke-width="1"/><rect x="${x + w / 2 - 5}" y="${base - h - 8}" width="10" height="6" rx="2" fill="none" stroke="#263238" stroke-width="2"/><line x1="${x + w * .3}" y1="${base - h}" x2="${x + w * .3}" y2="${base - 4}" stroke="#000" opacity=".2" stroke-width="2"/><circle cx="${x + 4}" cy="${base - 1}" r="2" fill="#263238"/><circle cx="${x + w - 4}" cy="${base - 1}" r="2" fill="#263238"/>`;
  const carroMaletas = x => `<rect x="${x}" y="${FL - 10}" width="70" height="5" fill="#D4A537" stroke="#8D6E00"/>` + [x + 8, x + 62].map(c => `<circle cx="${c}" cy="${FL - 3}" r="4" fill="#263238"/>`).join('') + `<path d="M${x + 4},${FL - 10} v-70 q0,-10 10,-10 h42 q10,0 10,10 v70" stroke="#D4A537" stroke-width="4" fill="none"/><line x1="${x + 4}" y1="${FL - 50}" x2="${x + 66}" y2="${FL - 50}" stroke="#D4A537" stroke-width="3"/>`
    + maleta(x + 8, FL - 10, 26, 34, '#1565C0') + maleta(x + 36, FL - 10, 24, 28, '#C62828') + maleta(x + 16, FL - 52, 34, 14, '#5D4037');
  const fachada = (noche) => `<rect x="20" y="50" width="280" height="${noche ? 100 : 90}" fill="${noche ? '#5D5348' : '#EFE6D8'}"/><path d="M10,52 L160,20 L310,52 z" fill="${noche ? '#3E2723' : '#6D4C41'}"/>` + [40, 90, 200, 250].map(x => `<rect x="${x}" y="68" width="30" height="24" fill="${noche ? '#FFE082' : '#BBDEFB'}" stroke="#ECEFF1" stroke-width="2"/>`).join('') + `<rect x="140" y="84" width="40" height="56" fill="#0E3962"/><rect x="146" y="92" width="28" height="40" fill="${noche ? '#FFE082' : '#90CAF9'}" opacity=".8"/>`;
  const estacionamiento = () => `<rect y="140" width="320" height="60" fill="#616161"/><rect y="140" width="320" height="3" fill="#9E9E9E"/>` + [40, 140, 240].map(x => `<rect x="${x}" y="182" width="40" height="3" fill="#FAFAFA"/>`).join('');
  const auto = (x, base, c = '#0E3962') => `<path d="M${x},${base - 16} v-22 q0,-8 10,-10 l26,-4 l26,-24 h70 q12,0 20,14 l14,14 q14,2 14,12 v20 z" fill="${c}" stroke="#263238" stroke-width="1.4"/><path d="M${x + 66},${base - 56} l-20,20 h44 v-20 z M${x + 96},${base - 56} v20 h50 l-12,-16 q-4,-4 -10,-4 z" fill="#B3E5FC" stroke="#263238"/><rect x="${x}" y="${base - 30}" width="190" height="4" fill="#D4A537"/><rect x="${x + 180}" y="${base - 34}" width="8" height="8" fill="#FFFFFF"/><rect x="${x + 2}" y="${base - 34}" width="8" height="6" fill="#FFF59D"/>` + [x + 40, x + 150].map(c2 => `<circle cx="${c2}" cy="${base - 14}" r="14" fill="#263238"/><circle cx="${c2}" cy="${base - 14}" r="6" fill="#B0BEC5"/>`).join('');
  const cuaderno = (x, y) => `<rect x="${x}" y="${y}" width="120" height="84" rx="4" fill="#FFFFFF" stroke="#90A4AE" stroke-width="1.5"/><rect x="${x}" y="${y}" width="8" height="84" fill="#0E3962"/>` + [0, 1, 2, 3, 4, 5].map(i => `<line x1="${x + 16}" y1="${y + 16 + i * 11}" x2="${x + 110}" y2="${y + 16 + i * 11}" stroke="#BBDEFB" stroke-width="1.5"/>`).join('') + [0, 1, 2].map(i => `<rect x="${x + 18}" y="${y + 10 + i * 11}" width="${60 + (i % 2) * 20}" height="3" fill="#455A64"/>`).join('');
  const recepcionista = (x, o) => W(x, 165, R(Object.assign({ hair: true }, o)));
  const ESC = () => H.fondo.recepcion();

  S.h_re_pub_intro = () => Z(ESC(), recepcionista(96) + mesonR(50, 120) + pantallaR(70) + W(214, 165, HU({ pose: 'stop', flip: true, face: 'worried' }, 1)) + enojo(232, 84) + maleta(248, 165, 20, 30) + bubble(186, 22, '¡Esto es inaceptable!', 130));
  S.h_re_pub_escuchar = () => Z(ESC(), recepcionista(96, { pose: 'point' }) + mesonR(50, 120) + pantallaR(70) + W(214, 165, HU({ flip: true }, 1)) + maleta(248, 165, 20, 30) + bubble(26, 22, 'Entiendo, lo voy a consultar', 170) + pill(110, 172, 'Tono bajo', '#2E7D32'));
