  const jeringa = (x, y, rot = 0, s = 1) => `<g transform="translate(${x},${y}) rotate(${rot}) scale(${s})"><rect x="-10" y="-2.5" width="18" height="5" rx="1" fill="#E3F2FD" stroke="#546E7A" stroke-width=".8"/><rect x="-10" y="-2.5" width="8" height="5" fill="#FFB74D" opacity=".7"/><rect x="-15" y="-1" width="5" height="2" fill="#546E7A"/><rect x="-16" y="-3" width="2" height="6" fill="#546E7A"/><rect x="8" y="-1.2" width="3" height="2.4" fill="#FF7043"/><line x1="11" y1="0" x2="20" y2="0" stroke="#78909C" stroke-width="1"/></g>`;
