  const paños = (x, y) => `<path d="M${x},${y} q-2,-14 10,-16 q4,-8 14,-4 q10,-4 14,6 q8,4 4,14 z" fill="#FFE0B2" stroke="#A1887F" stroke-width="1.2"/>` + [[x + 10, y - 10], [x + 24, y - 14], [x + 32, y - 6]].map(([a, b]) => `<ellipse cx="${a}" cy="${b}" rx="5" ry="3" fill="#6D4C41" opacity=".7"/>`).join('');
