  SI_CONT.temas.push({
    id: 'hb_camas', sec: 'habitaciones', emp: ['hotel'], title: 'Hacer camas y aseo de habitaciones sin dañar la espalda', thumb: 'h_hb_cama_rodilla', mins: 15,
    learn: [
      { s: 'h_hb_cama_riesgo', t: 'Tu espalda en cada habitación', x: 'En un turno haces muchas camas: estiras sábanas, levantas colchones, metes ropa bajo el colchón, aspiras y te agachas a limpiar. Cada movimiento parece pequeño, pero repetido cientos de veces <b>cansa la espalda, los hombros y las rodillas</b>. Las lesiones de espalda son de las más comunes en el aseo de habitaciones, y casi todas se evitan con la postura correcta y pausas.' },
      { s: 'h_hb_cama_rodilla', t: 'Rodillas dobladas, espalda recta', x: '<ul><li>Para meter la sábana bajo el colchón, <b>dobla las rodillas o apoya una rodilla en el piso</b>, con la espalda recta.</li><li>No te dobles por la cintura con las piernas rectas.</li><li>Acércate a la cama: no te estires sobre ella.</li><li><b>Rodea la cama</b> y trabaja cada lado desde su costado.</li></ul>', k: 'Dobla las rodillas o apoya una rodilla en el piso; no dobles la espalda.' },
      { s: 'h_hb_colchon', t: 'El colchón se levanta entre dos', x: 'Un colchón de hotel pesa <b>entre 20 y 40 kilos</b> y es difícil de tomar. Para meter las sábanas basta con levantar <b>solo la esquina</b>, usando las piernas. Para darlo vuelta, rotarlo o sacarlo de la cama, <b>pide ayuda y háganlo entre dos</b>. La ley fija 25 kilos como máximo para levantar sin ayuda mecánica, pero mucho menos te puede lesionar si lo haces mal.' },
      { s: 'h_hb_cama_torcer', t: 'Gira con los pies, no con la cintura', x: 'Torcer el tronco mientras sostienes ropa de cama o toallas es una de las formas más fáciles de lesionar la espalda. Para dejar la ropa sucia en el carro o tomar la limpia, <b>da un paso y gira con los pies</b>, de frente a donde vas. Deja el carro cerca de la cama para no estirarte ni girar con peso.' },
      { s: 'h_hb_aspiradora', t: 'La aspiradora y su cable', x: '<ul><li>Aspira con el brazo y dando pasos, <b>sin doblar la espalda</b>.</li><li>Revisa que el <b>cable y el enchufe</b> estén sanos; si están pelados o quemados, no la uses y avisa.</li><li>Lleva el cable <b>junto a la pared</b>, nunca cruzando el pasillo por donde pasan huéspedes.</li><li>Desenchufa tomando el enchufe, no tirando del cable, y nunca con las manos mojadas.</li></ul>' },
      { s: 'h_hb_alto', t: 'Para lo alto: escala, no sillas', x: 'Para alcanzar la repisa del clóset, una cortina o una lámpara alta, usa una <b>escala de tijera</b> en buen estado, abierta completa y sobre piso firme, sin subir a los dos últimos peldaños. <b>Nunca te subas</b> a sillas, veladores, camas, maletas ni al borde de la tina: se mueven o se resbalan y la caída es de espaldas.', k: 'Para alcanzar lo alto usa una escala, nunca sillas ni muebles.' },
      { s: 'h_hb_muebles', t: 'Mover muebles', x: '<ul><li>Antes de moverlo, <b>vacíalo</b>: saca los cajones y lo que tenga encima.</li><li>Si se puede, <b>empújalo o deslízalo</b> en vez de levantarlo.</li><li>Camas, sillones y muebles pesados se mueven <b>entre dos</b>.</li><li>Cuida los dedos al pasar por puertas y al bajarlo.</li><li>No muevas muebles sobre alfombras sueltas o pisos mojados.</li></ul>' },
      { s: 'h_hb_pausas', t: 'Alterna tareas y haz pausas', x: 'Intercala tareas: camas, baño, polvo y aspirado, para no repetir siempre el mismo movimiento. Haz <b>pausas cortas</b> para estirar la espalda, los brazos y las piernas, y toma agua. Si sientes un dolor que no se pasa, hormigueo o adormecimiento, <b>avisa a tu jefatura</b> desde el principio: tratado a tiempo en la ACHS se recupera mejor.' }
    ],
    quiz: [
      { s: 'h_hb_cama_q', v: [
        { q: 'Vas a meter la sábana bajo el colchón. ¿Cuál es la postura correcta?', o: ['Doblar las rodillas o apoyar una rodilla en el piso, con la espalda recta', 'Doblarse por la cintura con las piernas rectas, para hacerlo rápido', 'Sentarse sobre la cama y estirarse hacia el otro lado', 'Inclinarse sobre la cama apoyando una mano en el colchón'], w: 'Bajar con las rodillas, o con una rodilla en el piso, deja la espalda recta y el esfuerzo en las piernas.' },
        { q: 'Tienes que estirar la sábana del lado de la cama que da a la pared. ¿Qué haces?', o: ['Rodeo la cama y la estiro desde ese costado', 'Me estiro por encima de la cama desde el otro lado', 'Me subo de rodillas a la cama para alcanzar', 'La dejo arrugada, porque no se ve'], w: 'Rodear la cama evita estirarse y doblar la espalda sobre el colchón.' },
        { q: 'Hacer camas doblando la espalda con las piernas rectas no daña si eres joven y estás en forma.', vf: false, w: 'Falso. La espalda se daña de a poco con cada repetición, a cualquier edad. Se trabaja con rodillas dobladas y espalda recta.' } ] },
      { s: 'h_hb_colchon_q', v: [
        { q: 'Hay que dar vuelta el colchón de una cama matrimonial. ¿Cómo se hace?', o: ['Entre dos personas, levantando con las piernas', 'Sola, si tienes experiencia y fuerza', 'Arrastrándolo sola hasta el suelo', 'Levantándolo sola por una esquina hasta voltearlo'], w: 'Un colchón pesa entre 20 y 40 kilos y es difícil de tomar: se da vuelta entre dos.' },
        { q: 'Para meter la sábana bajo el colchón, ¿cuánto lo levantas?', o: ['Solo la esquina, usando las piernas', 'El colchón completo, sobre la cabeza', 'Todo un costado, con la espalda doblada', 'Nada: la empujo con fuerza con los dedos'], w: 'Basta con levantar la esquina, doblando las rodillas, para meter la sábana.' },
        { q: '¿Cuánto puede pesar un colchón de hotel?', o: ['Entre 20 y 40 kilos', 'Entre 2 y 4 kilos', 'Menos de 10 kilos siempre', 'Más de 100 kilos siempre'], w: 'Los colchones pesan entre 20 y 40 kilos: por eso se mueven entre dos.' } ] },
      { s: 'h_hb_cama_torcer', v: [
        { q: 'Sacaste la ropa de cama y el carro está detrás de ti. ¿Cómo la dejas en el carro?', o: ['Doy un paso y giro con los pies, de frente al carro', 'Giro solo la cintura, sin mover los pies', 'La lanzo hacia atrás sin mirar', 'Me estiro hacia atrás con los brazos'], w: 'Girar con los pies evita torcer la espalda con peso.' },
        { q: '¿Qué movimiento daña más la espalda al hacer camas?', o: ['Torcer el tronco mientras sostienes peso', 'Caminar alrededor de la cama', 'Doblar las rodillas para bajar', 'Dejar el carro cerca de la cama'], w: 'Torcer la cintura con peso en las manos carga mucho la columna.' },
        { q: '¿Dónde conviene dejar el carro mientras haces la cama?', o: ['Cerca de la cama, para no estirarme ni girar con peso', 'Lejos, en el otro extremo del pasillo', 'Detrás de mí, para tenerlo a mano', 'Fuera del piso, en la escalera'], w: 'Con el carro cerca das menos pasos y no te tuerces con la ropa en las manos.' } ] },
      { s: 'h_hb_aspiradora', v: [
        { q: '¿Por dónde llevas el cable de la aspiradora?', o: ['Junto a la pared, sin cruzar el pasillo', 'Cruzando el pasillo, por el camino más corto', 'Por debajo de la alfombra del pasillo', 'Colgando entre dos puertas'], w: 'Un cable cruzado en el pasillo hace tropezar a huéspedes y compañeros.' },
        { q: 'El cable de la aspiradora está pelado cerca del enchufe. ¿Qué haces?', o: ['No la uso y aviso a mi jefatura', 'Lo cubro con cinta y sigo', 'La uso con cuidado de no tocar esa parte', 'Lo corto y lo vuelvo a conectar'], w: 'Un cable dañado puede dar un golpe de corriente: no se usa y se avisa para repararlo.' },
        { q: '¿Cómo desenchufas la aspiradora?', o: ['Tomando el enchufe, con las manos secas', 'Tirando del cable desde lejos', 'Tirando del cable con las manos mojadas', 'Pisando el cable y tirando de la aspiradora'], w: 'Tirar del cable lo daña por dentro, y el agua conduce la corriente.' } ] },
      { s: 'h_hb_alto_q', v: [
        { q: 'Necesitas sacar una frazada de la repisa alta del clóset. ¿Qué usas?', o: ['Una escala de tijera en buen estado y abierta completa', 'La silla de la habitación', 'El velador, que es firme', 'La cama, parándome en el borde'], w: 'Sillas, veladores y camas se mueven o se hunden. Para lo alto se usa una escala.' },
        { q: '¿Cómo se usa bien la escala de tijera?', o: ['Abierta completa, sobre piso firme, sin subir a los dos últimos peldaños', 'Cerrada y apoyada contra la pared', 'Abierta a medias, para que ocupe menos espacio', 'Parada en el último peldaño para alcanzar más'], w: 'La escala se abre completa, se apoya en piso firme y no se sube a los dos últimos peldaños.' },
        { q: 'Subirse al borde de la tina para limpiar la parte alta de la pared es seguro si lo haces con cuidado.', vf: false, w: 'Falso. El borde de la tina es angosto y resbaloso. Usa una escobilla de mango largo o una escala.' } ] },
      { s: 'h_hb_muebles', v: [
        { q: 'Tienes que mover un velador con cajones. ¿Qué haces primero?', o: ['Lo vacío y saco los cajones', 'Lo levanto de una vez con todo adentro', 'Lo arrastro de lado con la cadera', 'Lo inclino hasta que caigan los cajones'], w: 'Vacío pesa menos, y los cajones no se caen sobre tus pies.' },
        { q: '¿Cómo se mueve un sillón pesado?', o: ['Entre dos, o empujándolo si se puede', 'Sola, levantándolo sobre la espalda', 'Sola, tirándolo hacia atrás', 'Levantándolo con los brazos estirados'], w: 'Lo pesado se mueve entre dos; si se puede deslizar, mejor empujar que levantar.' },
        { q: '¿Cuál es el máximo de peso que la ley permite levantar sin ayuda mecánica?', o: ['25 kilos', '50 kilos', '40 kilos', 'No hay máximo'], w: 'El Código del Trabajo fija 25 kilos, aunque menos peso también puede lesionarte si lo levantas mal.' } ] },
      { s: 'h_hb_pausas_q', v: [
        { q: 'Hace varios días sientes dolor en la espalda baja que no se pasa. ¿Qué haces?', o: ['Aviso a mi jefatura para atenderme en la ACHS', 'Sigo trabajando hasta que se pase solo', 'Tomo analgésicos y no digo nada', 'Espero a tener vacaciones para descansar'], w: 'Las molestias se avisan desde el principio: tratadas a tiempo se recuperan mejor.' },
        { q: '¿Para qué sirve alternar tareas, por ejemplo camas, baño y aspirado?', o: ['Para no repetir siempre el mismo movimiento', 'Para terminar más tarde el turno', 'Para que la jefatura no note el cansancio', 'Para usar menos productos de aseo'], w: 'Alternar tareas reparte el esfuerzo entre distintos músculos y articulaciones.' },
        { q: 'Las pausas cortas para estirar la espalda y tomar agua ayudan a prevenir lesiones.', vf: true, w: 'Verdadero. Las pausas permiten que los músculos se recuperen durante el turno.' } ] },
      { s: 'h_hb_cama_riesgo', v: [
        { q: '¿Por qué las camareras se lesionan tanto la espalda?', o: ['Porque repiten muchas veces posturas forzadas en cada turno', 'Porque las camas de hotel son muy altas', 'Porque las sábanas pesan más de 25 kilos', 'Porque solo trabajan de pie'], w: 'Movimientos pequeños, repetidos cientos de veces con mala postura, terminan dañando la espalda.' },
        { q: '¿Qué partes del cuerpo se cansan más al hacer camas y aseo?', o: ['La espalda, los hombros y las rodillas', 'Solo los ojos y el cuello', 'Solo los pies', 'Solo las manos'], w: 'Agacharse, estirarse y levantar cargan la espalda, los hombros y las rodillas.' },
        { q: 'Una molestia leve en la espalda no es importante y no hace falta avisarla.', vf: false, w: 'Falso. Avisar a tiempo permite corregir la tarea y tratar la molestia antes de que sea una lesión.' } ] }
    ]
  });

