  SI_CONT.temas.push({
    id: 'hb_banos', sec: 'habitaciones', emp: ['hotel'], title: 'Aseo de baños: químicos, resbalones y pinchazos', thumb: 'h_hb_bano_mezcla', mins: 15,
    learn: [
      { s: 'h_hb_bano_riesgos', t: 'Los riesgos del baño', x: 'El baño es la parte de la habitación con más riesgos:<ul><li><b>Químicos</b> de aseo: cloro, desincrustantes, limpiadores.</li><li><b>Piso mojado</b> y con jabón.</li><li><b>Objetos cortopunzantes</b> en la basura: agujas, hojas de afeitar, vidrios.</li><li><b>Fluidos</b> como sangre o vómito.</li></ul>Con los guantes, el orden y los cuidados correctos, todos se controlan.' },
      { s: 'h_hb_bano_guantes', t: 'Guantes de goma y etiqueta', x: 'Para limpiar baños y usar químicos ponte <b>guantes de goma</b>, sin roturas. Antes de usar un producto, <b>lee su etiqueta</b>: dice para qué sirve, cómo diluirlo y qué peligros tiene. La <b>HDS</b> (Hoja de Datos de Seguridad) de cada producto indica el EPP: si dice antiparras o mascarilla, úsalas. Mantén cada químico en su envase original, nunca en botellas de bebida.' },
      { s: 'h_hb_bano_mezcla', t: 'Nunca mezcles productos', x: 'El <b>cloro mezclado con un ácido</b>, como un desincrustante o antisarro, o con amoníaco, libera un <b>gas tóxico</b> que daña los pulmones en minutos, y en un baño cerrado se concentra rápido. Nunca mezcles productos "para que limpie más". Usa <b>un producto a la vez</b>, enjuaga con agua y recién después el siguiente.', k: 'Nunca mezcles cloro con otros productos de aseo.' },
      { s: 'h_hb_bano_ventila', t: 'Ventila mientras limpias', x: 'Abre la <b>ventana</b> o enciende el <b>extractor</b> y deja la puerta abierta mientras limpias. Rocía de cerca sobre la superficie, nunca hacia tu cara. Si te pican los ojos, toses o te mareas, <b>sal al aire libre</b> y avisa a tu jefatura. Si un producto te salpica los ojos, lávalos con abundante agua por al menos 15 minutos y avisa.' },
      { s: 'h_hb_bano_piso', t: 'Piso mojado y alturas en el baño', x: '<ul><li>El piso del baño y de la ducha <b>resbala mucho con jabón</b>: sécalo al terminar.</li><li>Pon el <b>letrero de piso mojado</b> cuando limpies pasillos o áreas comunes.</li><li>Para la parte alta de las paredes usa una <b>escobilla de mango largo</b>.</li><li><b>Nunca te subas</b> al borde de la tina ni al inodoro.</li></ul>' },
      { s: 'h_hb_bano_basura', t: 'Agujas, hojas de afeitar y vidrios', x: 'Hay huéspedes que botan <b>agujas de insulina</b>, hojas de afeitar o vidrios rotos en el basurero. Por eso:<ul><li><b>Nunca presiones la bolsa</b> con la mano ni con el pie para que quepa más.</li><li>No metas la mano dentro del basurero.</li><li>Saca la bolsa <b>tomándola por arriba</b>, lejos del cuerpo, sin abrazarla ni apoyarla en las piernas.</li></ul>', k: 'Nunca presiones la bolsa de basura; sácala por arriba y lejos del cuerpo.' },
      { s: 'h_hb_bano_pinchazo', t: 'Si encuentras una aguja o te pinchas', x: 'Si ves una aguja o una hoja de afeitar suelta, <b>no la tomes con los dedos</b>: usa una pinza o escobillón y pala, y échala en un <b>envase rígido con tapa</b>; luego avisa. Si te pinchas o te cortas: lava con agua y jabón, no chupes la herida, <b>avisa de inmediato</b> y ve a la ACHS el mismo día, porque la atención debe ser rápida.' },
      { s: 'h_hb_bano_fluidos', t: 'Ropa con sangre, vómito u otros fluidos', x: '<ul><li>Ponte <b>guantes</b> antes de tocarla.</li><li><b>No la sacudas</b>: esparce gérmenes por el aire.</li><li>Enróllala con lo sucio hacia adentro y no la apoyes en tu cuerpo.</li><li>Ponla en una <b>bolsa aparte</b>, como indique tu jefatura, para que lavandería sepa lo que lleva.</li><li>Al terminar, sácate los guantes y <b>lávate las manos</b>.</li></ul>' }
    ],
    quiz: [
      { s: 'h_hb_mezcla_q', v: [
        { q: 'El baño tiene mucho sarro y una compañera propone mezclar cloro con antisarro para que limpie más. ¿Qué haces?', o: ['No los mezclo: uso uno, enjuago y después el otro', 'Los mezclo en el balde con agua caliente', 'Los mezclo, pero con la ventana abierta', 'Los mezclo en poca cantidad, para probar'], w: 'El cloro con un ácido libera un gas tóxico. Se usa un producto a la vez, enjuagando entre uno y otro.' },
        { q: '¿Qué pasa si mezclas cloro con un desincrustante o con amoníaco?', o: ['Se libera un gas tóxico que daña los pulmones', 'Limpia el doble y más rápido', 'Se pierde el olor del cloro y nada más', 'Se forma una espuma que no es peligrosa'], w: 'La mezcla libera un gas tóxico que en un baño cerrado se concentra en minutos.' },
        { q: 'Si se ventila bien el baño, se puede mezclar cloro con otros productos.', vf: false, w: 'Falso. La mezcla libera gas tóxico igual. Nunca se mezclan productos de aseo.' } ] },
      { s: 'h_hb_bano_guantes', v: [
        { q: 'Vas a limpiar el baño con productos químicos. ¿Qué te pones?', o: ['Guantes de goma sin roturas y el EPP que indique la HDS', 'Guantes de lana para no mojarte', 'Solo el delantal, sin guantes', 'Guantes de goma rotos, si la rotura es pequeña'], w: 'Los guantes de goma sanos protegen la piel; la HDS dice si además necesitas antiparras o mascarilla.' },
        { q: '¿Dónde encuentras los peligros y el EPP que necesita un producto de aseo?', o: ['En su etiqueta y en su Hoja de Datos de Seguridad', 'En el letrero de piso mojado', 'En la boleta de compra del producto', 'En el registro de habitaciones'], w: 'La etiqueta y la HDS indican peligros, dilución, EPP y primeros auxilios.' },
        { q: 'Se te terminó la botella y quieres pasar cloro a una botella vacía de bebida. ¿Qué corresponde?', o: ['No hacerlo: el químico va en su envase original o rotulado', 'Hacerlo, si la botella está limpia', 'Hacerlo, marcándola con un plumón', 'Hacerlo, si la guardas en tu carro'], w: 'En una botella de bebida alguien puede confundirlo y tomarlo.' } ] },
      { s: 'h_hb_bano_ventila', v: [
        { q: 'Mientras limpias el baño te empiezan a picar los ojos y toses. ¿Qué haces?', o: ['Salgo al aire libre y aviso a mi jefatura', 'Sigo limpiando, para terminar rápido', 'Cierro la puerta para que no salga el olor', 'Echo más producto para terminar antes'], w: 'Son señales de que respiraste vapores del producto: sal al aire y avisa.' },
        { q: '¿Qué haces antes de empezar a limpiar el baño con químicos?', o: ['Abro la ventana o enciendo el extractor', 'Cierro la puerta para concentrar el producto', 'Apago el extractor para no gastar luz', 'Rocío el producto en el aire para perfumar'], w: 'Ventilar evita que los vapores del producto se acumulen en el baño.' },
        { q: 'Te salpicó limpiador a un ojo. ¿Qué haces?', o: ['Lavo con abundante agua al menos 15 minutos y aviso', 'Me froto el ojo con el guante', 'Espero a que se pase solo', 'Me pongo gotas de cualquier remedio'], w: 'Agua abundante por al menos 15 minutos, y avisar para atenderte en la ACHS.' } ] },
      { s: 'h_hb_bano_piso', v: [
        { q: 'Tienes que limpiar la parte alta de la pared de la ducha. ¿Cómo lo haces?', o: ['Con una escobilla de mango largo, parada en el piso', 'Subida al borde de la tina', 'Subida sobre el inodoro', 'Subida a un piso de plástico mojado'], w: 'El borde de la tina y el inodoro son angostos y resbalosos: usa un mango largo.' },
        { q: '¿Por qué hay que secar el piso del baño al terminar?', o: ['Porque con agua y jabón resbala mucho', 'Porque el agua mancha la cerámica', 'Porque así se gasta menos producto', 'Porque lo pide el huésped siempre'], w: 'El agua con jabón deja el piso muy resbaloso para ti y para el huésped.' },
        { q: 'Al limpiar un pasillo o un área común, el letrero de piso mojado se pone antes de empezar.', vf: true, w: 'Verdadero. Así nadie pisa el piso mojado sin saberlo.' } ] },
      { s: 'h_hb_basura_q', v: [
        { q: 'El basurero del baño está lleno. ¿Cómo sacas la bolsa?', o: ['Tomándola por arriba, lejos del cuerpo, sin presionarla', 'Apretándola con la mano para que quepa más', 'Abrazándola contra el cuerpo para que no se rompa', 'Pisándola dentro del basurero para cerrarla'], w: 'En la basura puede haber agujas u hojas de afeitar: no se presiona y se toma por arriba.' },
        { q: '¿Por qué nunca se presiona la bolsa de basura con la mano o el pie?', o: ['Porque puede haber agujas, hojas de afeitar o vidrios adentro', 'Porque la bolsa se arruga y se ve mal', 'Porque así se gastan más bolsas', 'Porque el basurero se raya'], w: 'Una aguja o un vidrio atraviesan la bolsa y el guante con facilidad.' },
        { q: 'Con guantes de goma puedes meter la mano al basurero sin riesgo.', vf: false, w: 'Falso. Una aguja o una hoja de afeitar atraviesan el guante de goma. No se mete la mano.' } ] },
      { s: 'h_hb_pinchazo_q', v: [
        { q: 'Te pinchaste con una aguja que estaba en la basura. ¿Qué haces?', o: ['Lavo con agua y jabón, aviso de inmediato y voy a la ACHS el mismo día', 'Me chupo el dedo y sigo trabajando', 'Me pongo una curita y lo aviso al final de la semana', 'Espero unos días para ver si se infecta'], w: 'Un pinchazo con una aguja usada necesita atención rápida en la ACHS.' },
        { q: 'Encuentras una hoja de afeitar en el piso del baño. ¿Cómo la recoges?', o: ['Con pinza o escobillón y pala, y la echo en un envase rígido', 'Con los dedos, con cuidado', 'Con los dedos, pero con guantes de goma', 'La empujo debajo del mueble del lavamanos'], w: 'No se toma con los dedos: se recoge con pinza o pala y va a un envase rígido con tapa.' },
        { q: '¿Dónde se echa una aguja que encontraste?', o: ['En un envase rígido con tapa, y aviso', 'En la bolsa de basura común', 'En el inodoro', 'En el bolsillo del delantal hasta el final del turno'], w: 'El envase rígido evita que alguien más se pinche.' } ] },
      { s: 'h_hb_fluidos_q', v: [
        { q: 'Encuentras una sábana con sangre. ¿Cómo la sacas?', o: ['Con guantes, sin sacudirla, enrollándola con lo sucio hacia adentro', 'Sacudiéndola fuerte para ver si tiene algo', 'Sin guantes, si la mancha está seca', 'Abrazándola para llevarla rápido al carro'], w: 'Con guantes, sin sacudir y enrollada hacia adentro, para no tocar ni esparcir los fluidos.' },
        { q: '¿Por qué no se sacude la ropa de cama con vómito o sangre?', o: ['Porque esparce gérmenes por el aire', 'Porque se arruga más', 'Porque se rompen las costuras', 'Porque se mancha el piso'], w: 'Sacudirla lanza gérmenes al aire y sobre ti.' },
        { q: '¿Qué haces después de sacar ropa con fluidos y quitarte los guantes?', o: ['Me lavo las manos', 'Sigo con la siguiente habitación sin lavarme', 'Me limpio las manos en el delantal', 'Vuelvo a usar los mismos guantes en otra pieza sin lavarlos'], w: 'Lavarse las manos al sacarse los guantes elimina lo que haya quedado en la piel.' } ] },
      { s: 'h_hb_bano_riesgos', v: [
        { q: '¿Cuál de estos es un riesgo del aseo de baños?', o: ['Agujas u hojas de afeitar en la basura', 'La luz de la lámpara del velador', 'El ruido del pasillo', 'El color de las toallas'], w: 'En la basura del baño pueden venir objetos cortopunzantes.' },
        { q: '¿Qué riesgos encuentras en el baño de una habitación?', o: ['Químicos, piso mojado, cortopunzantes y fluidos', 'Solo el piso mojado', 'Solo el olor de los productos', 'Ninguno, si el huésped lo dejó ordenado'], w: 'El baño concentra varios riesgos: químicos, resbalones, pinchazos y fluidos.' },
        { q: 'Si el baño se ve limpio, no es necesario usar guantes para limpiarlo.', vf: false, w: 'Falso. Los químicos y lo que no se ve dañan igual: se usan guantes de goma siempre.' } ] }
    ]
  });

