      + `<rect x="${x0 + 60}" y="154" width="26" height="10" fill="#8D6E63"/>` + `<rect x="${x0 + 128}" y="${46}" width="26" height="108" fill="#A1887F"/>${[0, 1, 2, 3, 4, 5].map(i => `<line x1="${x0 + 128}" y1="${56 + i * 16}" x2="${x0 + 154}" y2="${56 + i * 16}" stroke="#6D4C41" stroke-width="2"/>`).join('')}`
