  SI_CONT.temas.push({
    id: 'lv_maquinas', sec: 'lavanderia', emp: ['hotel'], title: 'Lavadoras y secadoras industriales', thumb: 'h_lv_sala', mins: 15,
    learn: [
      { s: 'h_lv_sala', t: 'Las máquinas de la lavandería', x: 'Las <b>lavadoras industriales</b> centrifugan a gran velocidad y mueven mucho peso de ropa mojada. Las <b>secadoras</b> trabajan con aire muy caliente. Bien usadas son seguras, pero mal usadas pueden causar <b>atrapamientos, quemaduras, golpes de corriente e incendios</b>. Úsalas solo si te enseñaron a hacerlo, y sigue las instrucciones de cada máquina.' },
      { s: 'h_lv_tambor', t: 'No abras hasta que el tambor se detenga', x: 'Después del centrifugado, el tambor <b>sigue girando por inercia</b> un rato, aunque la pantalla diga que terminó. <b>Espera que se detenga por completo</b> antes de abrir la puerta. <b>Nunca metas las manos</b> con el tambor en movimiento: la ropa se enreda en el brazo y lo arrastra con mucha fuerza.', k: 'Espera que el tambor se detenga por completo antes de abrir o meter las manos.' },
      { s: 'h_lv_enclave', t: 'El seguro de la puerta', x: 'Las lavadoras y secadoras tienen un <b>seguro de la puerta</b> que impide abrirla mientras el tambor gira. Nunca lo fuerces, lo puentees ni lo anules. Si una puerta se abre con el tambor girando, o la máquina parte con la puerta abierta, <b>no la uses</b>: déjala con un aviso de "no usar" y avisa a tu jefatura para que la revise un técnico.' },
      { s: 'h_lv_carga', t: 'Carga sin sobrecargar', x: '<ul><li>Respeta la <b>capacidad en kilos</b> que indica la placa de la máquina: la sobrecarga la desequilibra y hace vibrar.</li><li>La ropa mojada pesa mucho más que la seca: <b>sácala de a poco</b>.</li><li>Pon el <b>carro junto a la puerta</b> y baja con las rodillas, sin doblar la espalda.</li><li>No tires la ropa de un tirón fuerte.</li></ul>' },
      { s: 'h_lv_filtro', t: 'El filtro de pelusa, en cada ciclo', x: 'La pelusa de la ropa es <b>muy inflamable</b>. Si se acumula en el filtro y en los ductos, la secadora se recalienta y puede <b>comenzar un incendio</b>. Por eso, <b>limpia el filtro de pelusa en cada ciclo</b>, con la secadora detenida, y bota la pelusa en el basurero. Si ves pelusa acumulada en los ductos o la ropa demora mucho en secarse, avisa.', k: 'Limpia el filtro de pelusa de la secadora en cada ciclo.' },
      { s: 'h_lv_aceite', t: 'Paños con aceite o químicos: no a la secadora', x: 'Los paños de cocina o de mantención con <b>aceite, cera, grasa o solventes</b> pueden <b>encenderse solos</b> con el calor, incluso después de terminar el ciclo, al quedar amontonados. Lávalos bien antes de secar y avisa si siguen con restos. Si sale <b>humo</b> de una secadora: <b>no abras la puerta</b>, porque entra aire y aviva el fuego; detenla si es seguro, aleja a todos y da la alarma.' },
      { s: 'h_lv_caliente', t: 'Ropa y superficies calientes', x: 'La ropa recién secada, el tambor y los botones o cierres metálicos <b>queman</b>. Deja que la secadora termine su <b>ciclo de enfriamiento</b> antes de sacar la ropa. No toques el vidrio de la puerta ni las paredes calientes de la máquina, y no dejes la ropa caliente amontonada: repártela o dóblala pronto para que se enfríe.' },
      { s: 'h_lv_electrico', t: 'Electricidad, agua y piso', x: '<ul><li>Nunca toques enchufes, interruptores ni tableros con las <b>manos mojadas</b> o pisando agua.</li><li>Si ves un cable dañado o una máquina que da corriente, no la uses y avisa.</li><li>Seca el agua y el detergente del piso de inmediato y pon el <b>letrero de piso mojado</b>.</li><li>Las reparaciones las hace solo mantención o el técnico.</li></ul>' }
    ],
    quiz: [
      { s: 'h_lv_tambor_q', v: [
        { q: 'La lavadora terminó el centrifugado, pero el tambor todavía gira. ¿Qué haces?', o: ['Espero que se detenga por completo antes de abrir', 'Abro y saco la ropa mientras frena', 'Meto la mano para frenar el tambor', 'Abro de un tirón para que pare antes'], w: 'El tambor sigue girando por inercia: se abre solo cuando está totalmente detenido.' },
        { q: '¿Por qué nunca se meten las manos con el tambor en movimiento?', o: ['Porque la ropa se enreda en el brazo y lo arrastra con fuerza', 'Porque la ropa se puede desteñir', 'Porque se gasta más agua', 'Porque la máquina se desordena'], w: 'Un tambor girando tiene mucha fuerza: puede fracturar o arrancar un brazo.' },
        { q: 'Si la pantalla dice que el lavado terminó, el tambor ya está detenido.', vf: false, w: 'Falso. El tambor puede seguir girando por inercia. Mira que esté totalmente detenido.' } ] },
      { s: 'h_lv_enclave', v: [
        { q: 'La puerta de una lavadora se abrió con el tambor girando. ¿Qué haces?', o: ['No la uso, la dejo con aviso de no usar y aviso a mi jefatura', 'La sigo usando, cerrando la puerta con cuidado', 'La amarro con una cuerda para que no se abra', 'La uso solo con cargas pequeñas'], w: 'Si el seguro falla, la máquina no se usa hasta que la revise un técnico.' },
        { q: '¿Para qué sirve el seguro de la puerta de la lavadora?', o: ['Para que no se pueda abrir mientras el tambor gira', 'Para que no se escape el olor del detergente', 'Para que nadie se robe la ropa', 'Para ahorrar energía'], w: 'El seguro impide que alguien meta la mano con el tambor en movimiento.' },
        { q: 'Se puede puentear el seguro de la puerta para sacar la ropa más rápido.', vf: false, w: 'Falso. El seguro nunca se fuerza, se puentea ni se anula.' } ] },
      { s: 'h_lv_carga', v: [
        { q: '¿Cuánta ropa puedes poner en la lavadora?', o: ['La capacidad en kilos que indica la placa, sin pasarme', 'Toda la que quepa apretándola', 'El doble de la placa si es ropa liviana', 'Lo que alcance a cerrar la puerta'], w: 'La sobrecarga desequilibra la máquina, la hace vibrar y la daña.' },
        { q: '¿Cómo sacas la ropa mojada de la lavadora?', o: ['De a poco, con el carro junto a la puerta y bajando con las rodillas', 'De una vez, de un tirón fuerte', 'Doblando la espalda con las piernas rectas', 'Con un pie apoyado en la máquina para hacer fuerza'], w: 'La ropa mojada pesa mucho: se saca de a poco y con buena postura.' },
        { q: '¿Qué puede pasar si sobrecargas la lavadora?', o: ['Se desequilibra, vibra fuerte y se puede dañar', 'Lava mejor y más rápido', 'Gasta menos detergente sin problema', 'Seca la ropa más rápido'], w: 'Una carga excesiva desequilibra el tambor en el centrifugado.' } ] },
      { s: 'h_lv_filtro_q', v: [
        { q: '¿Cada cuánto se limpia el filtro de pelusa de la secadora?', o: ['En cada ciclo', 'Una vez al mes', 'Solo cuando se nota tapado', 'Una vez al año, en la mantención'], w: 'La pelusa acumulada es muy inflamable: el filtro se limpia en cada ciclo.' },
        { q: '¿Por qué es peligrosa la pelusa acumulada en la secadora?', o: ['Porque es muy inflamable y puede causar un incendio', 'Porque mancha la ropa limpia', 'Porque hace que la ropa encoja', 'Porque da mal olor a la lavandería'], w: 'La pelusa se enciende con facilidad con el calor de la secadora.' },
        { q: 'Si la ropa demora mucho más de lo normal en secarse, puede haber pelusa acumulada en los ductos y hay que avisar.', vf: true, w: 'Verdadero. Un ducto tapado recalienta la secadora y aumenta el riesgo de incendio.' } ] },
      { s: 'h_lv_aceite_q', v: [
        { q: 'Llegan paños de mantención con manchas de aceite. ¿Qué haces?', o: ['No los meto a la secadora con restos de aceite; los lavo bien y aviso', 'Los meto a la secadora a máxima temperatura', 'Los seco junto con las sábanas', 'Los dejo amontonados calientes en el carro'], w: 'Los paños con aceite pueden encenderse solos con el calor.' },
        { q: '¿Qué puede pasar con paños con aceite o solventes después de secarlos?', o: ['Pueden encenderse solos al quedar amontonados y calientes', 'Se ponen más blancos', 'Se encogen y nada más', 'Pierden el color'], w: 'El aceite se calienta solo dentro del montón de paños y puede prenderse.' },
        { q: 'Los paños con restos de cera o grasa se pueden secar sin problema si se usa poca temperatura.', vf: false, w: 'Falso. Igual pueden encenderse solos. Se lavan bien antes y se avisa si siguen con restos.' } ] },
      { s: 'h_lv_humo_q', v: [
        { q: 'Ves salir humo de una secadora en marcha. ¿Qué haces?', o: ['No abro la puerta, la detengo si es seguro, alejo a todos y doy la alarma', 'Abro la puerta para sacar la ropa', 'Echo agua por la puerta abierta', 'Espero que termine el ciclo para revisar'], w: 'Abrir la puerta deja entrar aire y aviva el fuego.' },
        { q: '¿Por qué no se abre la puerta de una secadora que echa humo?', o: ['Porque entra aire y el fuego se aviva', 'Porque la ropa se arruga', 'Porque se pierde el calor del ciclo', 'Porque se puede trabar la puerta'], w: 'Sin aire, el fuego tiene menos fuerza. Abrir la puerta lo alimenta.' },
        { q: 'Si sale humo de la secadora, lo primero es abrir la puerta para ver qué pasa.', vf: false, w: 'Falso. La puerta se mantiene cerrada; se detiene la máquina si es seguro, se aleja a todos y se da la alarma.' } ] },
      { s: 'h_lv_caliente', v: [
        { q: '¿Cuándo sacas la ropa de la secadora?', o: ['Cuando termina el ciclo de enfriamiento', 'Apenas para, aunque esté muy caliente', 'Con el tambor todavía girando', 'Cuando la pantalla muestra la temperatura máxima'], w: 'El ciclo de enfriamiento evita quemaduras y que la ropa caliente se amontone.' },
        { q: '¿Qué partes de la ropa recién secada queman más?', o: ['Los botones y cierres metálicos', 'Las etiquetas de papel', 'Los bordes de las toallas', 'Las fundas de algodón'], w: 'El metal se calienta mucho y quema la piel.' },
        { q: 'Dejar la ropa caliente amontonada no tiene ningún riesgo.', vf: false, w: 'Falso. La ropa caliente amontonada puede quemarte y, con restos de aceite, hasta encenderse.' } ] },
      { s: 'h_lv_electrico', v: [
        { q: 'Tienes las manos mojadas y necesitas encender una máquina. ¿Qué haces?', o: ['Me seco las manos y me aseguro de no pisar agua', 'La enciendo rápido, sin tocar mucho el interruptor', 'Uso un guante mojado para no tocar el interruptor', 'Le pido a otro que la encienda pisando el charco'], w: 'El agua conduce la corriente: manos secas y piso seco.' },
        { q: 'Hay agua con detergente en el piso junto a una lavadora. ¿Qué haces?', o: ['La seco de inmediato y pongo el letrero de piso mojado', 'La dejo, porque se seca sola', 'Paso por encima con cuidado', 'Le echo una toalla encima y sigo'], w: 'El agua con detergente es muy resbalosa y además es un riesgo eléctrico.' },
        { q: '¿Quién repara una lavadora que da corriente?', o: ['Solo mantención o el técnico, y mientras tanto no se usa', 'Cualquiera que sepa de electricidad', 'Yo, si tengo un destornillador', 'Nadie: se sigue usando con guantes de goma'], w: 'Una máquina que da corriente no se usa y la repara personal autorizado.' } ] }
    ]
  });

