  const cross = (x, y, r = 10) => `<path d="M${x - r},${y - r} L${x + r},${y + r} M${x + r},${y - r} L${x - r},${y + r}" stroke="#D7262B" stroke-width="5" stroke-linecap="round"/>`;
  const nofumar = (x, y, r = 14) => `<circle cx="${x}" cy="${y}" r="${r}" fill="#fff" stroke="#D7262B" stroke-width="3.5"/><rect x="${x - r * .6}" y="${y - 2}" width="${r * .95}" height="4.5" fill="#455A64"/><rect x="${x + r * .35}" y="${y - 2}" width="${r * .25}" height="4.5" fill="#FF7043"/><line x1="${f1(x - r * .7)}" y1="${f1(y - r * .7)}" x2="${f1(x + r * .7)}" y2="${f1(y + r * .7)}" stroke="#D7262B" stroke-width="3.5"/>`;
