  const banco = (x, y, w) => `<rect x="${x}" y="${y - 40}" width="${w}" height="6" fill="#795548" stroke="#4E342E"/><rect x="${x + 4}" y="${y - 34}" width="5" height="34" fill="#5D4037"/><rect x="${x + w - 9}" y="${y - 34}" width="5" height="34" fill="#5D4037"/><rect x="${x + 4}" y="${y - 12}" width="${w - 8}" height="3" fill="#5D4037"/>`;
