  const kit = (x, y, s = 1) => `<g transform="translate(${x},${y}) scale(${s})"><rect x="0" y="0" width="56" height="40" rx="4" fill="#fff" stroke="#90A4AE" stroke-width="1.4"/>`
    + [['#FFF59D', '#FDD835', '#F9A825', '#F57F17'], ['#FFCDD2', '#EF9A9A', '#E57373', '#C62828']].map((cs, k) => `<rect x="${6 + k * 26}" y="6" width="9" height="28" rx="4" fill="${cs[2]}" stroke="#78909C"/>` + cs.map((c, i) => `<rect x="${17 + k * 26}" y="${6 + i * 7}" width="6" height="6" fill="${c}"/>`).join('')).join('')
    + T(15, 47, 'CLORO', 5.5, '#455A64') + T(41, 47, 'pH', 6, '#455A64') + '</g>';
  // filtro de arena de la piscina
  const filtro = (x, y) => `<rect x="${x - 2}" y="${y - 4}" width="44" height="4" fill="#616161"/><path d="M${x},${y - 4} V${y - 56} Q${x},${y - 72} ${x + 20},${y - 72} Q${x + 40},${y - 72} ${x + 40},${y - 56} V${y - 4} Z" fill="#1E88E5" stroke="#0D47A1" stroke-width="1.6"/>`
    + `<rect x="${x + 12}" y="${y - 84}" width="16" height="12" rx="2" fill="#ECEFF1" stroke="#78909C"/><path d="M${x + 20},${y - 84} v-6 h10" stroke="#263238" stroke-width="3" stroke-linecap="round"/>` + dial(x + 6, y - 82, 5) + `<path d="M${x + 28},${y - 78} h14" stroke="#ECEFF1" stroke-width="6"/>`;
  // bomba de la piscina con prefiltro (tapa transparente)
  const bombaPis = (x, y, o = {}) => `<rect x="${x - 2}" y="${y - 4}" width="62" height="4" fill="#616161"/><rect x="${x}" y="${y - 30}" width="20" height="26" rx="4" fill="#ECEFF1" stroke="#78909C" stroke-width="1.4"/><rect x="${x + 2}" y="${y - 38}" width="16" height="9" rx="3" fill="#B3E5FC" fill-opacity=".8" stroke="#4FC3F7"/>`
    + `<rect x="${x + 20}" y="${y - 26}" width="38" height="20" rx="5" fill="#455A64" stroke="${OL}" stroke-width="1.2"/>` + [0, 1, 2, 3].map(i => `<line x1="${x + 26 + i * 8}" y1="${y - 25}" x2="${x + 26 + i * 8}" y2="${y - 7}" stroke="#37474F" stroke-width="1.2"/>`).join('')
    + `<path d="M${x},${y - 18} h-14 M${x + 10},${y - 38} v-30" stroke="#ECEFF1" stroke-width="6"/>` + (o.run ? `<g class="h_mt_vi"><path d="M${x + 60},${y - 22} q4,-4 8,0" stroke="#90A4AE" stroke-width="1.6" fill="none"/></g>` : '');
  const salaB = () => `<rect width="320" height="200" fill="#DCE3E8"/>` + [...Array(12)].map((_, i) => `<line x1="${i * 28}" y1="110" x2="${i * 28}" y2="165" stroke="#C5D0D6" stroke-width="1.2"/>`).join('') + `<line x1="0" y1="110" x2="320" y2="110" stroke="#C5D0D6" stroke-width="1.2"/><line x1="0" y1="138" x2="320" y2="138" stroke="#C5D0D6" stroke-width="1.2"/>`
    + `<rect y="165" width="320" height="35" fill="#90A4AE"/><rect y="165" width="320" height="3" fill="#000" opacity=".08"/>`;
  const bodegaQ = () => `<rect width="320" height="200" fill="#E6E1D6"/><rect y="165" width="320" height="35" fill="#A1A1A1"/><rect y="165" width="320" height="3" fill="#000" opacity=".08"/>`;
  const repisa = (x, y, w) => `<rect x="${x}" y="${y}" width="${w}" height="5" fill="#8D6E63" stroke="#5D4037"/><rect x="${x + 3}" y="${y + 5}" width="3" height="${165 - y - 5}" fill="#6D4C41"/><rect x="${x + w - 6}" y="${y + 5}" width="3" height="${165 - y - 5}" fill="#6D4C41"/>`;
  const rejilla = (x, y, w = 40, h = 20) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#78909C" stroke="#546E7A"/>` + [...Array(Math.floor(h / 4))].map((_, i) => `<line x1="${x + 2}" y1="${y + 3 + i * 4}" x2="${x + w - 2}" y2="${y + 3 + i * 4}" stroke="#ECEFF1" stroke-width="1.6"/>`).join('');
  const gasCloro = (x, y, s = 1) => [0, 1, 2].map(i => `<g class="h_mt_gas" style="animation-delay:-${i}s"><ellipse cx="${x + (i - 1) * 16 * s}" cy="${y - i * 8 * s}" rx="${18 * s}" ry="${11 * s}" fill="#C5E1A5" opacity=".75"/></g>`).join('');
  const salvavidas = (x, y, r = 12) => `<circle cx="${x}" cy="${y}" r="${r}" fill="none" stroke="#D7262B" stroke-width="${r * .5}"/>` + [0, 1, 2, 3].map(i => `<path d="M${f1(x + r * 1.25 * Math.cos(i * 1.571 + .785))},${f1(y + r * 1.25 * Math.sin(i * 1.571 + .785))} L${f1(x + r * .75 * Math.cos(i * 1.571 + .785))},${f1(y + r * .75 * Math.sin(i * 1.571 + .785))}" stroke="#fff" stroke-width="${r * .5}"/>`).join('');
  const cartel = (x, y, w, l1, l2, c = '#D7262B') => `<rect x="${x + w / 2 - 2}" y="${y + 30}" width="4" height="${172 - y - 30}" fill="#78909C"/><rect x="${x}" y="${y}" width="${w}" height="30" fill="#fff" stroke="${c}" stroke-width="2.5"/>` + T(x + w / 2, y + 13, l1, 8, c) + T(x + w / 2, y + 24, l2 || '', 8, c);
