  const pino = (x, y, h, sway) => { const w = h * .36; return `<rect x="${x - 4}" y="${y - h * .3}" width="8" height="${h * .3}" fill="#6D4C41"/>` + `<g${sway ? ' class="h_mt_sw"' : ''}>` + [0, 1, 2].map(i => `<path d="M${x},${f1(y - h + i * h * .2)} L${f1(x + w * (.55 + i * .22))},${f1(y - h * .62 + i * h * .2)} L${f1(x - w * (.55 + i * .22))},${f1(y - h * .62 + i * h * .2)} Z" fill="${['#2E7D32', '#388E3C', '#2E7D32'][i]}"/>`).join('') + `<rect x="${x - 3}" y="${f1(y - h * .45)}" width="6" height="${f1(h * .16)}" fill="#5D4037"/></g>`; };

