    return V(H.fondo.jardin() + msaw(lg[0], lg[1], { freno: true }) + `<line x1="${f1(lg[0] + 6.5)}" y1="${f1(lg[1] + 1)}" x2="${f1(hx2)}" y2="${f1(hy2)}" stroke="#263238" stroke-width="1"/>` + PMS(lx, ly, L)
      + pill(80, 12, 'En el suelo y con freno', '#2E7D32', 10) + badge(140, 52, true, 14) + divider()
      + msaw(rg[0], rg[1], { run: true }) + `<line x1="${f1(rg[0] + 6.5)}" y1="${f1(rg[1] + 1)}" x2="${f1(rcx)}" y2="${f1(rcy)}" stroke="#263238" stroke-width="1"/>` + PMS(rx, ry, R) + pill(240, 12, 'Nunca "al aire"', '#D7262B') + badge(300, 52, false, 14));
