  SI_CONT.temas.push({
    id: 'mt_motosierra', sec: 'mantencion', emp: ['hotel'], title: 'Motosierra: uso seguro', thumb: 'h_mt_ms_epp', mins: 20,
    learn: [
      { s: 'h_mt_ms_intro', t: 'La motosierra en el parque y el bosque', x: 'Con la motosierra se podan y cortan árboles, ramas y troncos del parque y del bosque del hotel. Es una de las herramientas más peligrosas: la cadena corta ropa y piel en un instante. Sus riesgos son <b>cortes graves, rebote de la espada, caída de árboles y ramas, ruido, vibración y quemaduras</b> con el escape. Solo la usa quien está <b>capacitado y autorizado</b> por su jefatura.' },
      { s: 'h_mt_ms_epp', t: 'EPP completo, siempre', x: 'Antes de encenderla, ponte todo el EPP:<ul><li><b>Casco con visor de malla y protector auditivo</b>.</li><li><b>Pantalón o chaparreras anticorte</b>: sus fibras traban la cadena.</li><li><b>Guantes</b> de cuero.</li><li><b>Calzado de seguridad</b> con puntera y suela firme.</li></ul>Usa ropa ajustada, sin bufandas ni partes sueltas. Si te falta algo, pídelo a tu jefatura antes de partir.', k: 'Sin el EPP completo, la motosierra no se enciende.' },
      { s: 'h_mt_ms_partes', t: 'Revisa la motosierra antes de usarla', x: 'Con el motor apagado, revisa:<ul><li><b>Freno de cadena</b>: al empujar la protección delantera, la cadena queda trabada.</li><li><b>Cadena afilada y tensa</b>: no cuelga bajo la espada y se puede girar con la mano enguantada.</li><li>Acelerador con su seguro, que vuelve solo al soltarlo.</li><li>Manillas, espada y tornillos firmes, y sin fugas de combustible.</li></ul>Si algo falla, no se usa: avisa a tu jefatura.' },
      { s: 'h_mt_ms_arranque', t: 'Arranque y traslado', x: 'Arranca siempre con el <b>freno de cadena puesto</b>:<ul><li><b>En el suelo</b>: pie en la manilla trasera, mano en la manilla delantera y tira la cuerda.</li><li><b>Entre las piernas</b>: la manilla trasera apretada entre los muslos.</li></ul>Nunca la arranques <b>"al aire"</b>, soltándola mientras tiras la cuerda. Para moverte de un lugar a otro, pon el freno o apaga el motor, y lleva la espada hacia atrás con su protector.' },
      { s: 'h_mt_ms_rebote', t: 'El rebote o "patada"', x: 'Si la <b>punta superior de la espada</b> toca una rama, un tronco o el suelo, la motosierra salta de golpe hacia arriba, hacia tu cara. Es el accidente más grave con motosierra. Para evitarlo:<ul><li>Nunca cortes con la punta.</li><li>Tómala con <b>las dos manos</b>, con el pulgar rodeando la manilla.</li><li>Mira siempre dónde está la punta.</li><li>Revisa que el freno de cadena funcione.</li></ul>', k: 'Nunca cortes con la punta de la espada.' },
      { s: 'h_mt_ms_hombros', t: 'Postura y altura de corte', x: 'Corta siempre <b>bajo la altura de tus hombros</b>: más arriba pierdes el control y la espada queda cerca de tu cara. Párate firme, con los pies separados y en suelo despejado, y deja tu cuerpo fuera de la línea de la cadena. <b>Nunca uses la motosierra subido a una escala</b> ni con una sola mano. Si la rama está muy alta, la poda se planifica con tu jefatura.' },
      { s: 'h_mt_ms_derribo', t: 'Derribo: zona de seguridad', x: 'Al derribar un árbol, la <b>zona de seguridad es de dos veces la altura del árbol</b> a la redonda: ahí no puede haber nadie más. Delimítala con cinta y conos, y mantén a los <b>huéspedes lejos</b>, también en senderos y estacionamientos. Planifica la dirección de caída y tu vía de escape en diagonal hacia atrás. <b>Nunca trabajes solo</b>: un compañero debe estar a la vista, fuera de la zona.', k: 'En un derribo, nadie dentro de dos alturas del árbol, y nunca trabajes solo.' },
      { s: 'h_mt_ms_comb', t: 'Combustible y cansancio', x: '<ul><li>Carga combustible con el <b>motor apagado y frío</b>, lejos de fuego y sin fumar.</li><li>Usa un bidón rotulado y limpia lo que se derrame.</li><li>Arranca a unos 3 metros del lugar donde cargaste.</li></ul>La motosierra pesa y vibra: el <b>cansancio</b> causa errores. Haz pausas, toma agua y no la uses con sueño, enfermo, ni bajo efectos del alcohol o de medicamentos que den sueño.' }
    ],
    quiz: [
      { s: 'h_mt_ms_q_epp', v: [
        { q: '¿Qué EPP necesitas para usar la motosierra?', o: ['Casco con visor, protector auditivo, pantalón anticorte, guantes y calzado de seguridad', 'Casco, lentes y guantes de goma, con tu ropa de trabajo de siempre', 'Protector auditivo y guantes de cuero, con zapatillas cómodas', 'Lentes de seguridad y mascarilla, con pantalón de mezclilla grueso'], w: 'La motosierra exige el EPP completo: casco con visor de malla y protector auditivo, pantalón o chaparreras anticorte, guantes y calzado de seguridad.' },
        { q: '¿Para qué sirve el pantalón o las chaparreras anticorte?', o: ['Sus fibras traban la cadena si llega a tocarte', 'Abrigan las piernas en los días fríos', 'Evitan que la resina manche la ropa', 'Protegen del agua cuando el pasto está mojado'], w: 'Las fibras del pantalón anticorte se enredan en la cadena y la frenan en un instante.' },
        { q: 'Para cortar una sola rama, se puede usar la motosierra sin el pantalón anticorte.', vf: false, w: 'Falso. Un corte grave ocurre en segundos: el EPP completo se usa siempre, aunque el trabajo sea corto.' }] },
      { s: 'h_mt_ms_partes', v: [
        { q: '¿Cómo compruebas que el freno de cadena funciona?', o: ['Empujo la protección delantera y la cadena debe quedar trabada', 'Acelero fuerte y miro si la cadena gira más rápido', 'Toco la cadena con la mano mientras gira lento', 'Reviso que la espada esté limpia y con aceite'], w: 'El freno de cadena se activa al empujar la protección delantera de la mano: la cadena debe quedar trabada.' },
        { q: 'Al revisar la motosierra ves que la cadena cuelga bajo la espada. ¿Qué significa?', o: ['Que está suelta y hay que tensarla antes de usarla', 'Que está bien, así corta más rápido', 'Que le falta combustible al motor', 'Que el freno de cadena está puesto'], w: 'Una cadena suelta puede salirse de la espada. Debe estar tensa, sin colgar, y poder girarse con la mano enguantada.' },
        { q: '¿Cuándo y cómo se revisa la motosierra?', o: ['Antes de cada uso, con el motor apagado', 'Una vez al mes, en la mantención general', 'Solo cuando empieza a fallar o a hacer ruido', 'Con el motor encendido, mientras corta'], w: 'Se revisa antes de cada uso y con el motor apagado: freno, cadena, acelerador, manillas y fugas.' }] },
      { s: 'h_mt_ms_q_arr', v: [
        { q: '¿Cuál es una forma correcta de arrancar la motosierra?', o: ['En el suelo, con el freno puesto y el pie en la manilla trasera', 'Sostenida en el aire con una mano mientras tiras la cuerda', 'Apoyada en la rodilla, con el freno de cadena suelto', 'Colgando del brazo, para que el motor parta más rápido'], w: 'Se arranca en el suelo o entre las piernas, con el freno de cadena puesto. Nunca "al aire".' },
        { q: 'Un compañero arranca la motosierra "al aire", soltándola mientras tira la cuerda. ¿Qué le dices?', o: ['Que es peligroso: debe arrancarla en el suelo o entre las piernas', 'Que está bien si después la toma firme con las dos manos', 'Que está bien si usa el pantalón anticorte', 'Que está bien si la cadena está bien afilada'], w: 'Arrancar "al aire" deja la motosierra sin control con la cadena girando. Se arranca en el suelo o entre las piernas, con el freno puesto.' },
        { q: 'La motosierra se arranca con el freno de cadena puesto.', vf: true, w: 'Verdadero. Con el freno puesto, la cadena no gira cuando parte el motor.' }] },
      { s: 'h_mt_ms_q_cerca', v: [
        { q: '¿Qué parte de la espada produce el rebote o "patada"?', o: ['La punta superior de la espada', 'La parte de abajo, cerca del motor', 'El centro de la espada, por abajo', 'Las espigas junto al cuerpo de la motosierra'], w: 'Si la punta superior de la espada toca algo, la motosierra salta hacia arriba, hacia tu cara.' },
        { q: '¿Qué ayuda a evitar el rebote de la motosierra?', o: ['No cortar con la punta y sujetarla con las dos manos', 'Cortar despacio, con el motor casi detenido', 'Sujetarla con una mano para moverla mejor', 'Usar una cadena sin filo, que salta menos'], w: 'No se corta con la punta, se sujeta con las dos manos, con el pulgar rodeando la manilla, y el freno de cadena debe funcionar.' },
        { q: 'Si ocurre un rebote, ¿hacia dónde salta la motosierra?', o: ['Hacia arriba, hacia la cara de quien corta', 'Hacia abajo, contra el suelo', 'Hacia adelante, lejos de quien corta', 'Hacia el lado, sin peligro para nadie'], w: 'El rebote lanza la espada hacia arriba y hacia atrás, hacia la cabeza y la cara de quien la usa.' }] },
      { s: 'h_mt_ms_q_rama', v: [
        { q: 'Debes cortar una rama que está sobre tu cabeza. ¿Qué haces?', o: ['No la corto con motosierra sobre mis hombros: lo planifico con mi jefatura', 'La corto con los brazos estirados hacia arriba', 'Me subo a una escala y la corto con la motosierra', 'La corto con una sola mano para alcanzar más alto'], w: 'La motosierra se usa bajo la altura de los hombros y nunca subido a una escala.' },
        { q: '¿Hasta qué altura se puede cortar con la motosierra?', o: ['Bajo la altura de los hombros', 'Hasta la altura de la cabeza', 'Hasta donde alcancen los brazos estirados', 'A cualquier altura, si usas casco con visor'], w: 'Sobre los hombros pierdes el control y la espada queda cerca de tu cara.' },
        { q: 'Si una rama está muy alta, se puede usar la motosierra subido a una escala.', vf: false, w: 'Falso. Nunca se usa la motosierra subido a una escala: una sacudida o un rebote te hacen caer.' }] },
      { s: 'h_mt_ms_derribo', v: [
        { q: 'Se va a derribar un árbol de 10 metros de alto. ¿De cuánto es la zona de seguridad?', o: ['20 metros a la redonda', '10 metros a la redonda', '5 metros a la redonda', '15 metros, solo hacia donde cae'], w: 'La zona de seguridad es de dos veces la altura del árbol: para 10 metros de alto, 20 metros a la redonda.' },
        { q: '¿Quién puede estar dentro de la zona de seguridad durante un derribo?', o: ['Solo quien corta con la motosierra', 'Quien corta y un ayudante que empuje el árbol', 'Los huéspedes, si se quedan quietos', 'Cualquier trabajador que use casco'], w: 'Dentro de dos alturas del árbol solo está quien corta. El compañero mira desde afuera de la zona.' },
        { q: 'Antes del corte de derribo, ¿qué debes planificar?', o: ['La dirección de caída y tu vía de escape en diagonal hacia atrás', 'Solo el tiempo que te tomará el corte', 'Dónde dejarás la motosierra encendida', 'Cuántos trozos de leña saldrán del árbol'], w: 'Se planifica hacia dónde caerá el árbol y por dónde te alejarás, en diagonal hacia atrás.' }] },
      { s: 'h_mt_ms_q_huesped', v: [
        { q: 'Estás cortando troncos y se acerca un huésped con un niño a mirar. ¿Qué haces?', o: ['Detengo el corte, pongo el freno y les pido con respeto que se alejen', 'Sigo cortando, porque todavía están a unos pasos', 'Les pido que se queden detrás de mí', 'Acelero para terminar antes de que lleguen'], w: 'Las astillas, las ramas o la cadena pueden herirlos. Se detiene el trabajo y se les pide con respeto que se alejen.' },
        { q: 'Debes derribar un árbol en el bosque del hotel. ¿Cómo trabajas?', o: ['Con un compañero a la vista, fuera de la zona de seguridad', 'Solo, así nadie queda dentro de la zona', 'Solo, avisando por teléfono cuando termines', 'Con un compañero sujetando el árbol junto a ti'], w: 'En un derribo nunca se trabaja solo: si ocurre un accidente, alguien debe poder ayudarte y pedir auxilio.' },
        { q: 'Para que los huéspedes no entren al área de corte, la zona se delimita con cinta y conos.', vf: true, w: 'Verdadero. La zona se delimita, también en senderos y estacionamientos, y se mantiene a los huéspedes lejos.' }] },
      { s: 'h_mt_ms_q_comb', v: [
        { q: '¿Cómo se carga combustible a la motosierra?', o: ['Con el motor apagado y frío, lejos de fuego', 'Con el motor andando despacio, para no volver a arrancarla', 'Recién apagada, para no perder tiempo', 'Junto a la fogata, donde hay más luz'], w: 'Con el motor apagado y frío, lejos de fuego, sin fumar y con un bidón rotulado.' },
        { q: 'Terminaste de cargar combustible. ¿Dónde arrancas la motosierra?', o: ['A unos 3 metros del lugar donde cargué', 'En el mismo lugar, sobre el combustible que cayó', 'Junto al bidón, para guardarlo después', 'Dentro de la bodega, para no hacer ruido afuera'], w: 'Se arranca alejado del lugar de carga: los vapores y el combustible derramado pueden encenderse.' },
        { q: 'Llevas horas con la motosierra y tienes los brazos cansados. ¿Qué haces?', o: ['Hago una pausa antes de seguir', 'Sigo, para terminar antes', 'La tomo con una mano para descansar la otra', 'Acelero más para cortar más rápido'], w: 'El cansancio causa errores y pérdida de control. Se hacen pausas y se toma agua.' }] }
    ]
  });

  // ======================================================================
